window.DATA=[{"id": "d1_thomas", "dzien": 1, "postac": "Thomas Ward, 71", "glos": "Grzecznie, trochę staroświecko. Żartuje z własnej drżącej ręki.", "typ": "uczciwy, wstydliwy", "rzecz": "Lewa skórzana rękawiczka, zszyta białą nitką przy kciuku", "wnetrze": [{"sekret_id": "d1_kwit_0417", "co_widac": "W mankiecie tkwi kwit z tego biura, numer 0417, sprzed trzech tygodni. Odręcznie: „Prawa wydana bez wpisu. Lewa czeka. S.H.” W księdze wydań nie ma wpisu o tym numerze, w tym miejscu wyrwano stronę.", "co_z_tego_wynika": "Thomas już tu był i dostał coś, czego nigdzie nie zapisano. Poprzednik wydawał rzeczy poza księgą."}], "wejscie": "Dobry wieczór. Thomas Ward. Zgubiłem lewą rękawiczkę mojej żony, w tramwaju czwórce. Ellen zmarła w lutym. W niedzielę idę na cmentarz i nie chcę iść z jedną.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta rękawiczka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowa skóra, mały rozmiar. Przy kciuku zszyłem ją białą nitką, bo ciemnej nie miałem. Krzywo, ale trzyma.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy się zgubiła?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, wczoraj wieczorem, jak jechałem do Doków. Leżała mi na kolanie i zsunęła się pod siedzenie na zakręcie.", "mina": "neutralna"}, {"tekst": "Czemu rękawiczki żony były w tramwaju?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Noszę je w kieszeni, jedną w drugiej, jakbym trzymał ją za rękę. Głupie, wiem.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Na kogo wpisać tę rękawiczkę?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Na Ellen Ward. A mnie jako Thomas Ward, przez h.", "mina": "mowi"}, {"tekst": "Jak sprawdzić, że to właśnie ta?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Drugą mam w kieszeni. Proszę je położyć kciukami do siebie: w prawej nitka jest czarna, w lewej biała. Czarna mi się skończyła.", "mina": "neutralna"}, {"tekst": "Czy to pierwsza wizyta w tym biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Pierwsza. Z urzędami się nie zadaję.", "mina": "klamie"}, {"tekst": "W mankiecie jest kwit z tego biura, numer 0417. Skąd on?", "ton": "niewygodne", "wymaga": "d1_kwit_0417", "odpowiedz": "No dobrze, byłem tu. Trzy tygodnie temu zgubiłem prawą. Młody człowiek, Sam, oddał mi ją od ręki i powiedział, że wpisu nie trzeba, bo to pamiątka, a nie zguba. Wstydziłem się, że to drugi raz.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Jest jakiś dokument ze zdjęciem?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Jest dowód. Proszę, ręka mi drży, ale zdjęcie się zgadza.", "mina": "mowi"}, {"tekst": "Może ktoś jeszcze zgłosić się po tę rękawiczkę?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Córka, Claire. Ale ona nie wie, że rękawiczka się zgubiła. Jakby przyszła, niech jej ktoś powie, że wszystko w porządku.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli rękawiczka zostanie tu do niedzieli?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Pójdę na cmentarz z jedną. Ellen by się śmiała, że sto razy mi mówiła, żebym pilnował rzeczy.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Włożę je do jednej kieszeni, tam, gdzie były.", "zysk": "Thomas idzie w niedzielę na cmentarz z obiema rękawiczkami.", "strata": "Wydajesz na słowo i nitkę, a kwit 0417 zostaje w księdze bez wyjaśnienia.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dziękuję za rękawiczkę. W niedzielę pojechałem z Claire na cmentarz, obie leżały na kamieniu przez godzinę. Claire pyta, kim jest młody człowiek, który wcześniej oddał mi prawą bez papierka. Powiedziałem, że nie wiem, choć wiem. — T. Ward"}}, {"akcja": "zatrzymaj_sprawdz", "etykieta": "Zatrzymaj do sprawdzenia tożsamości", "reakcja": "Rozumiem. Przyjdę jutro z córką, ona ma dowód i wie, jak wygląda ta nitka.", "zysk": "Rękawiczka zostaje w biurze, dopóki ktoś nie potwierdzi, kim jest Thomas.", "strata": "Starszy człowiek wraca do domu z jedną rękawiczką, a niedziela na cmentarzu jest zagrożona.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Claire Ward: „Ojciec dwa dni nie wychodził z domu. Proszę oddać mu tę rękawiczkę, podpiszę za niego. I proszę mi powiedzieć, kto wcześniej oddał mu prawą bez żadnego papieru.”"}}, {"akcja": "wydaj_bez_wpisu", "etykieta": "Wydaj bez wpisu, tak jak zrobił to Sam", "reakcja": "Dziękuję. Tak samo jak ostatnio: bez papierka. Młody człowiek też tak powiedział.", "zysk": "Thomas ma obie rękawiczki od ręki i nikt się nie dowie, że biuro znów wydało coś poza księgą.", "strata": "Powtarzasz to, co robił poprzednik. Wydanie nie zostawia śladu i zalicza się do rachunku „bez wpisu”.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Thomas Ward: „Mówiłem Claire, że w tym biurze ludzie wydają od ręki. Nie powiedziałem jej, że to wasz drugi raz bez papierka.”"}}], "sprite": "rekawiczka_skora", "face": "wdowiec", "face2": null, "line": "4", "itemName": "rękawiczka", "inside": {"img": "W1", "x": 0.2, "y": 0.72}}, {"id": "d1_rosa", "dzien": 1, "postac": "Rosa Vale, 33", "glos": "Zmęczona, praktyczna, liczy na głos. Krótkie zdania, suchy humor.", "typ": "uczciwa, ale nie ma jak tego udowodnić", "rzecz": "Brązowa koperta z wypłatą, jedna zszywka", "wnetrze": [{"sekret_id": "d1_lista_nocy", "co_widac": "W kopercie jest 129 dolarów i kartka z listą nocy: trzy odhaczone, czwarta przekreślona. Na odcinku zbiorczym stoi nazwisko I. Bell.", "co_z_tego_wynika": "Wypłatę odbierała i rozdzielała Iris Bell. Czwartą noc Rosy skreśliła Iris."}], "wejscie": "Dobry wieczór. Rosa Vale, pracuję w pralni pod estakadą. Zgubiłam kopertę z wypłatą, 129 dolarów, w jedenastce. Jutro mam czynsz, więc to cały mój tydzień.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta koperta?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowa, jedna zszywka. Zszywka weszła krzywo, bo kierownik zszywał na stojąco.", "mina": "mowi"}, {"tekst": "Gdzie i o której ją zgubiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, o szóstej rano. Położyłam ją obok, żeby zapiąć torbę, i zasnęłam do pętli.", "mina": "neutralna"}, {"tekst": "Skąd wiadomo, że było tam 129 dolarów?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo liczyłam. Trzy noce po 43 dolary, to daje 129. Przeliczyłam trzy razy.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Kto Ci wypłacił te pieniądze?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Iris Bell, zarządczyni naszej kamienicy. Odbiera wypłatę z pralni i rozdaje nam w domu. Koperta była od niej.", "mina": "mowi"}, {"tekst": "Co jeszcze jest w środku, poza pieniędzmi?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Kartka z naszymi nocami. Nic ważnego.", "mina": "neutralna"}, {"tekst": "Czemu wypłatę odbiera Iris, a nie same pracownice?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Tak ustaliła. Dla niej wygodnie, dla nas nie bardzo, ale mieszkamy u niej, więc nie dyskutuję.", "mina": "neutralna"}, {"tekst": "Na liście jedna noc jest przekreślona. Dlaczego?", "ton": "niewygodne", "wymaga": "d1_lista_nocy", "odpowiedz": "W czwartek wyszłam o północy, bo córka miała gorączkę. Iris skreśliła całą noc, nie połowę. Czterdzieści trzy dolary za cztery godziny, które przepracowałam. Nie chcę o tym gadać.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Przeliczysz pieniądze przy okienku?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Tak, proszę. Przy dwustu dolarach bym zaufała, ale przy stu dwudziestu dziewięciu liczę co do centa.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Rosa Vale, przez V. Podpiszę, jak przeliczę.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli wypłata nie wróci dzisiaj?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Spóźnię się z czynszem, a Iris liczy za to dwadzieścia dolarów kary. Dostanę sto dziewięć zamiast stu dwudziestu dziewięciu.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Przeliczę przy szybie. Sto dwadzieścia dziewięć, zgadza się. Dziękuję, serio.", "zysk": "Rosa ma czynsz na jutro, a w księdze jest jej podpis pod kwotą 129 dolarów.", "strata": "Odcinek zbiorczy jest wystawiony na Iris Bell, więc w papierach wypłata należała do kogoś innego, niż ją odbiera.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Iris zeszła do pralni i spytała, kto mi pozwolił odbierać pieniądze przez okienko. Powiedziałam, że nikt, że sama zgubiłam kopertę. Od przyszłego tygodnia odbieram wypłatę osobiście, bez niej. — Rosa"}}, {"akcja": "odmow", "reakcja": "Dobrze, powiedzcie Iris. Poczekam, tylko czynsz nie poczeka.", "zysk": "Koperta wraca do osoby wskazanej na odcinku, czyli do Iris, zgodnie z przepisem.", "strata": "Rosa płaci dwadzieścia dolarów kary za spóźniony czynsz.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Iris oddała mi kopertę z potrąceniem: sto dziewięć dolarów. Dwadzieścia za spóźniony czynsz, który sama pobiera. Powiedziała, że to formalność. — Rosa"}}, {"akcja": "wez_20", "etykieta": "Wydaj, ale odlicz sobie 20 $ „za fatygę”", "kasa": 20, "reakcja": "Sto dziewięć? Zaraz, przeliczę jeszcze raz. ...Brakuje dwudziestu dolarów. Nie powiem nic, bo kto mi uwierzy.", "zysk": "Dostajesz 20 dolarów do kieszeni, które nikomu nie zostały zapisane.", "strata": "Rosie brakuje dwudziestu dolarów do czynszu, a Iris nalicza jej za to jeszcze karę.", "echo": {"za_dni": 2, "forma": "list", "tekst": "W kopercie brakowało mi dwudziestu dolarów. Iris naliczyła karę za spóźniony czynsz, drugie dwadzieścia. Cztery dychy w plecy przez jedną noc. Nie mówię, że ktoś wziął. Mówię, że brakuje. — Rosa"}}, {"akcja": "przywlaszcz", "etykieta": "Zatrzymaj 129 $ dla siebie", "kasa": 129, "reakcja": "Nie ma? To ostatnie miejsce, gdzie szukałam. Dziękuję, że sprawdziłeś. Powiem pani Iris, że wypłata przepadła w tramwaju.", "zysk": "+129 $ w kieszeni: prawie cały czynsz za tydzień.", "strata": "Rosa wraca do domu bez wypłaty za całą nockę, a w księdze nie ma po kopercie śladu.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Sto dwadzieścia dziewięć dolarów, tyle było w kopercie. Ada pytała, czemu dziś na kolację tylko chleb. Pani Iris potrąci mi to z następnej wypłaty i nie chce słuchać. Wiem, że to nie twoja wina. Chciałam komuś to powiedzieć. Rosa"}}], "sprite": "koperta", "face": null, "face2": null, "line": "11", "itemName": "koperta", "inside": {"img": "W20", "x": 0.51, "y": 0.58}}, {"id": "d2_jonah", "dzien": 2, "postac": "Jonah Pike, 22", "glos": "Mówi szybko, poprawia się w pół zdania. Kiedy pada imię June, zwalnia.", "typ": "uczciwy, zdenerwowany", "rzecz": "Czarny plecak z pękniętą klamrą", "wnetrze": [{"sekret_id": "d2_paragon_raty", "co_widac": "W pudełku w kieszeni na plecach leży pierścionek z małym oczkiem. Obok paragon: wpłacone 40 dolarów, 200 zostało do spłaty w ratach. Na serwetce trzy wersje oświadczyn, dwie przekreślone.", "co_z_tego_wynika": "Jonah jutro o siódmej chce się oświadczyć, a pierścionek kupił na raty. Pierścionek jest wart w lombardzie około 150 dolarów."}], "wejscie": "Cześć, Jonah. Zgubiłem plecak w jedenastce, czarny, z pękniętą klamrą. Potrzebuję go na jutro rano, bo w kieszeni jest coś ważnego. Naprawdę ważnego.", "tury": [{"pytania": [{"tekst": "Co jest w plecaku?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Ładowarka, książka, mnóstwo biletów, nie wiem, czemu je zbieram. I pudełko w kieszeni na plecach. Pudełko jest najważniejsze.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy go zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, wczoraj wieczorem, pod składanym siedzeniem przy drzwiach. Wcisnąłem go nogą, żeby June miała gdzie stanąć.", "mina": "mowi"}, {"tekst": "Co jest w tym pudełku?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Prezent. Niespodzianka, więcej nie powiem.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Kim jest June?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Moją dziewczyną. Pracuje w piekarni, wstaje o czwartej. Jutro o siódmej, zanim wyjdzie, chcę ją o coś zapytać. Dlatego ten plecak.", "mina": "emocja"}, {"tekst": "Jak chcesz jej to powiedzieć?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W kuchni, zanim założy buty. Mam trzy wersje na serwetce. Żadna mi się nie podoba.", "mina": "mowi"}, {"tekst": "A jak odmówi?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "To będzie najgorszy poranek mojego życia. Ale wolę zapytać, niż się nie dowiedzieć.", "mina": "emocja"}, {"tekst": "Na paragonie jest 40 dolarów wpłaty i reszta na raty. Stać Cię na to?", "ton": "niewygodne", "wymaga": "d2_paragon_raty", "odpowiedz": "Nie stać. Wziąłem na sześć rat, jestem kurierem. Ale ona jest tego warta. I tak, wiem, jak to brzmi.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Zdążysz do domu przed siódmą?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Rowerem dziesięć minut. Zdążę z zapasem, byle ktoś mi go dał dzisiaj.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jonah Pike. Pike jak ta ryba.", "mina": "neutralna"}, {"tekst": "Co zrobisz, jeśli plecak nie wróci przed siódmą?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Przełożę, ale June od razu zauważy, że coś jest nie tak. Ona zawsze wie. Przy niej nie umiem kłamać.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki! Serio, dzięki. Lecę, zanim się rozmyślę.", "zysk": "Jonah wraca do domu z pierścionkiem i ma noc na ćwiczenie oświadczyn.", "strata": "Plecak wychodzi bez wpisu, bo Jonah prosi o dyskrecję, więc księga nie zna jego nazwiska.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Jonah: „Pierścionek jest w kieszeni, serwetka też. Jutro o siódmej. Trzymaj kciuki, jeśli masz kciuki.”"}}, {"akcja": "odmow", "reakcja": "Co? Ale to MÓJ plecak! Dobrze, dobrze, wrócę z kimś, kto potwierdzi.", "zysk": "Plecak zostaje w biurze do czasu dowodu własności.", "strata": "Jonah może nie zdążyć do siódmej, a June zauważy, że coś jest nie tak.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Jonah: „Odebrałem plecak dopiero rano, spóźniłem się. June chyba się domyśla. Pierścionek nadal mam.”"}}, {"akcja": "wez_pierscionek", "etykieta": "Zatrzymaj pierścionek, plecak wydaj", "kasa": 150, "reakcja": "Dziękuję, lecę. ...Eee, a pudełko? Jest puste! Zaraz, gdzie...? Ja... idę na policję.", "zysk": "Pierścionek wart w lombardzie 150 dolarów, czyli niemal czynsz.", "strata": "Jonah zgłasza kradzież na komisariacie, a oświadczyny rano upadają. Policja zapyta, kto miał plecak.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Noah Reyes: „Był tu mężczyzna z plecakiem. Zgłosił kradzież pierścionka z plecaka, który odebrał z biura rzeczy znalezionych. Czyli: jedno biuro, jedno nocne okienko. Zapiszę.”"}}], "sprite": "plecak", "face": "chlopak", "face2": null, "line": "11", "itemName": "plecak", "inside": null}, {"id": "d2_hana", "dzien": 2, "postac": "Hana Moreau, 26", "glos": "Mówi starannie, jakby recytowała. Przy kłamstwie podkreśla każdą sylabę.", "typ": "sympatyczna kłamczyni", "rzecz": "Czarny sztywny futerał na skrzypce z zieloną naklejką", "wnetrze": [{"sekret_id": "d2_etykieta_wyp", "co_widac": "Pod pokrywą futerału przyklejona kartka: „Własność Konserwatorium. Wypożyczone H. Moreau do 14 października.” Dzisiaj jest 15.", "co_z_tego_wynika": "Skrzypce nie są Hany. Jej wypożyczenie skończyło się wczoraj."}], "wejscie": "Dobry wieczór. Hana Moreau, skrzypaczka. Zgubiłam futerał ze skrzypcami w czwórce. O ósmej rano mam przesłuchanie do orkiestry i bez tych skrzypiec nie mam po co przychodzić.", "tury": [{"pytania": [{"tekst": "Jak wygląda futerał?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, sztywny, z mosiężnymi zamkami. W środku wieka zielona naklejka, a rączka owinięta czerwoną taśmą.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie go zostawiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, w ostatnim kursie. Postawiłam go między nogami, zadzwoniła mama i wysiadłam bez futerału.", "mina": "neutralna"}, {"tekst": "Czyje to są skrzypce?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Moje. Oczywiście, że moje. Gram na nich od siedmiu lat.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Co jeszcze jest w futerale?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Kalafonia, szmatka z jedwabiu i nuty Mendelssohna z moimi zapiskami ołówkiem.", "mina": "mowi"}, {"tekst": "Czy w skrzypcach jest etykieta lutnika?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jest, ale mała. Nazwiska nie pamiętam, od lat nie zaglądałam do środka.", "mina": "neutralna"}, {"tekst": "Dlaczego to takie pilne właśnie dzisiaj?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo przesłuchanie jest jutro o ósmej. Dostałam się z listy rezerwowej, drugiej szansy nie będzie.", "mina": "emocja"}, {"tekst": "Pod pokrywą jest kartka: wypożyczenie do 14 października. Co to znaczy?", "ton": "niewygodne", "wymaga": "d2_etykieta_wyp", "odpowiedz": "Że termin minął wczoraj. Konserwatorium nie przedłużyło, bo komisja zbiera się dopiero w poniedziałek. Nie jestem złodziejką, tylko spóźniłam się o dwa dni. Ale gram jutro.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Daleko stąd do filharmonii?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Cztery przystanki. Próba jest o siódmej, więc jeśli wyjdę stąd przed szóstą, zdążę rozgrzać palce.", "mina": "mowi"}, {"tekst": "Odbiór instrumentu wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Hana Moreau. Napiszę czytelnie, choć ręka mi drży od wczoraj.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli skrzypce wrócą do konserwatorium?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy ktoś inny zagra moje przesłuchanie, a mnie wykreślą z listy. Bez instrumentu nie wolno się pokazać.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. W poniedziałek pójdę do komisji, obiecuję. Najpierw zagram.", "zysk": "Hana zagra przesłuchanie i ma szansę dostać miejsce w orkiestrze.", "strata": "Oddajesz instrument konserwatorium komuś, komu wypożyczenie wygasło wczoraj.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Zagrałam. Nikt nie wiedział, że skrzypce są po terminie. W poniedziałek komisja przedłużyła mi wypożyczenie do końca roku. Przepraszam za zamieszanie. — H. Moreau"}}, {"akcja": "odmow", "reakcja": "Rozumiem. Skrzypce należą do konserwatorium. Proszę im powiedzieć, że byłam tu pierwsza.", "zysk": "Skrzypce wracają do prawdziwego właściciela, czyli do konserwatorium.", "strata": "Hana traci przesłuchanie i miejsce na liście.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Konserwatorium odebrało skrzypce i podziękowało za sumienność. Na przesłuchaniu zagrał ktoś inny. Ja gram teraz na altówce koleżanki w piwnicy. Nie mam żalu, ale mam dyplom. — H. Moreau"}}], "sprite": "futeral", "face": null, "face2": null, "line": "6", "itemName": "futerał na skrzypce", "inside": null}, {"id": "d3_maz_i_siostra", "dzien": 3, "postac": "Evan Doyle, 37, i Lena Brandt, 31", "glos": "Evan: grzecznie, pełnymi zdaniami, wraca do tego samego pytania. Lena: szybko, urywa, mówi za dużo.", "typ": "Evan kłamie, Lena mówi prawdę", "rzecz": "Czarny telefon w skórzanym etui z odklejonym rogiem", "ludzie": {"maz": "Evan", "siostra": "Lena"}, "wnetrze": [{"sekret_id": "d3_telefon_wiadomosc", "co_widac": "Na ekranie wisi wiadomość od „Lena” z czwartku, 23:48: „Nie wracaj do domu. Jadę po ciebie w sobotę.” Pod etui złożone stare zdjęcie dwóch dziewczynek, podpisane „Maya i Lena”.", "co_z_tego_wynika": "To telefon Mai. Siostra kazała jej nie wracać do męża. Maya zostawiła telefon celowo."}], "wejscie": "Dobry wieczór. Evan Doyle, a to Lena, siostra mojej żony. Oboje przyszliśmy po telefon Mai, która zaginęła w czwartek. Zostawiła go w jedenastce. Policja zamknie zgłoszenie do dwudziestego drugiego, więc to pilne.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten telefon?", "ton": "uprzejme", "kto": "maz", "wymaga": null, "odpowiedz": "Czarny, w skórzanym etui z odklejonym rogiem. Kupiłem jej to etui na rocznicę.", "mina": "mowi"}, {"tekst": "Kiedy Maya go zgubiła?", "ton": "rzeczowe", "kto": "siostra", "wymaga": null, "odpowiedz": "W czwartek wieczorem, w jedenastce. Nic więcej nie wiem.", "mina": "klamie"}, {"tekst": "Jak wyglądała Wasza ostatnia rozmowa z Mayą?", "ton": "niewygodne", "kto": "maz", "wymaga": null, "odpowiedz": "Zwyczajnie. Nie było żadnej kłótni. Zjedliśmy kolację, poszła do pracy i nie wróciła.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Co jest w tym telefonie?", "ton": "uprzejme", "kto": "siostra", "wymaga": null, "odpowiedz": "Zdjęcia, muzyka, kontakty. I trochę wiadomości ode mnie, zwykłe rzeczy między siostrami.", "mina": "mowi"}, {"tekst": "Po co policji ten telefon?", "ton": "rzeczowe", "kto": "maz", "wymaga": null, "odpowiedz": "Żeby sprawdzić, dokąd poszła. Policjant powiedział, że bez telefonu zgłoszenie rozstrzygnie się najpóźniej dwudziestego drugiego i na tym koniec.", "mina": "mowi"}, {"tekst": "Czy Maya miała powód, żeby odejść?", "ton": "niewygodne", "kto": "maz", "wymaga": null, "odpowiedz": "Żadnego. Mieliśmy spokojne małżeństwo. Oboje dużo pracowaliśmy, to wszystko.", "mina": "klamie"}, {"tekst": "SMS od Leny: „Nie wracaj do domu.” Co to znaczy?", "ton": "niewygodne", "kto": "siostra", "wymaga": "d3_telefon_wiadomosc", "odpowiedz": "To ja napisałam. Maya zadzwoniła w czwartek, że boi się wracać. Jak Evan to przeczyta, przyjdzie do mnie. Proszę nie dawać mu tego telefonu.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czy Maya wie, że tu jesteście?", "ton": "uprzejme", "kto": "siostra", "wymaga": null, "odpowiedz": "Nie. Od czwartku nie mam z nią kontaktu. Naprawdę.", "mina": "neutralna"}, {"tekst": "Co zrobisz z telefonem, jeśli go dostaniesz?", "ton": "rzeczowe", "kto": "maz", "wymaga": null, "odpowiedz": "Zaniosę go policjantowi, Reyesowi z komisariatu przy Rynku. Jeszcze dziś.", "mina": "mowi"}, {"tekst": "Co będzie, jeśli telefon zostanie w biurze?", "ton": "niewygodne", "kto": "maz", "wymaga": null, "odpowiedz": "Wtedy policja dostanie go za późno. Mogę się odwdzięczyć, sto dolarów od ręki i bez księgi. Dogadamy się?", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj_evan", "etykieta": "Wydaj telefon Evanowi", "kto": "maz", "reakcja": "Dziękuję. Idę z tym do Reyesa. Lena, nie patrz tak.", "zysk": "Evan zanosi telefon policjantowi, zgłoszenie dostaje materiał.", "strata": "Evan przeczyta wiadomość od Leny i pójdzie do niej z pretensjami, a Lena Ci tego nie zapomni.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Evan był u mnie wieczorem. Przeczytał wiadomość i krzyczał na klatce, aż sąsiadka wyszła. Powiedział, że biuro wydało mu telefon, więc teraz wie wszystko. — Lena"}}, {"akcja": "wydaj_lena", "etykieta": "Wydaj telefon Lenie", "kto": "siostra", "reakcja": "Dziękuję. Zabieram go do siebie. Evan, nie patrz tak na mnie, to rodzinne.", "zysk": "Lena zabiera telefon i wiadomość nie dociera do Evana.", "strata": "Evan zostaje bez śladu po żonie i przestaje ufać biuru.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Evan Doyle: „Wydano telefon mojej żony komuś innemu. Chcę wiedzieć komu i na jakiej podstawie. Jestem jej mężem.”"}}, {"akcja": "zatrzymaj", "etykieta": "Zatrzymaj telefon dla Mai", "reakcja": "To znaczy, że nikt go nie dostanie? A jeśli ona po niego nie przyjdzie?", "zysk": "Telefon leży w biurze, nikt go nie czyta.", "strata": "Evan i Lena wychodzą z niczym, a Maya nie wiadomo czy po telefon wróci.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Noah Reyes: „Doyle dzwoni do mnie co godzinę, że telefon żony jest w biurze i go nie wydają. Czyli: wiem, gdzie jest. Nie mówię, że to źle.”"}}, {"akcja": "wez_100_evan", "etykieta": "Wydaj telefon Evanowi i przyjmij od niego 100 $", "kasa": 100, "kto": "maz", "reakcja": "Proszę. Cieszę się, że się rozumiemy. Lena, idziemy.", "zysk": "Dostajesz 100 dolarów, więcej niż pół czynszu.", "strata": "Lena widzi, jak Evan podaje pieniądze, a Evan zna odtąd Twoją cenę i zapamięta, że można się dogadać.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Lena Brandt: „Widziałam, jak Evan podał kopertę, a okienko ją przyjęło. Nie wiem teraz, komu mogę zaufać. Proszę mi nie mówić, że to nie to, na co wyglądało.”"}}], "sprite": "telefon", "face": "maz", "face2": {"maz": "maz", "siostra": "siostra"}, "line": "11", "itemName": "telefon", "inside": null}, {"id": "d3_dana", "dzien": 3, "postac": "Dana Ruiz, 38", "glos": "Głośno, prosto, bez owijania. Mówi o budziku jak o koledze z pracy.", "typ": "uczciwa, rozbrajająca", "rzecz": "Blaszany budzik z dwoma dzwonkami", "wnetrze": [], "wejscie": "Cześć, Dana Ruiz, mechanik w zajezdni. Zgubiłam budzik w szóstce, taki blaszany, z dwoma dzwonkami. Bez niego nie wstanę na czwartą, a w zajezdni nikt nie czeka, jak ktoś się spóźni.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten budzik?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Blaszany, okrągły, dwa dzwonki na górze. Mam go od dwunastu lat i dzwoni tak, że sąsiad się budzi.", "mina": "mowi"}, {"tekst": "Na którą jest nastawiony?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na czwartą piętnaście. Wskazówka alarmu jest czerwona, krzywa, bo kiedyś ją naprawiałam kombinerkami.", "mina": "mowi"}, {"tekst": "Czemu zabierasz budzik do tramwaju?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo wczoraj poszłam spać u siostry. Nie chciałam go zostawić samego, wiesz, jak to jest.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co masz jeszcze w torbie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Klucz francuski, kanapkę i rękawice. Kanapka jest dla budzika, żartuję.", "mina": "mowi"}, {"tekst": "Czym potwierdzisz, że to Twój?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na spodzie jest naklejka „Mama”, bo mama mi go dała. I wgniecenie przy prawym dzwonku, jak spadł z lodówki.", "mina": "mowi"}, {"tekst": "Jak długo pracujesz w zajezdni?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Jedenaście lat. Znam tu każdy zawias. I wiem, że dzisiaj jeden mój budzik wydaje się komuś ważniejszy od mojej roboty.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Kiedy musisz być w zajezdni?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Za pięć piąta. Jak wstanę o czwartej piętnaście, zdążę na kawę. Jak nie, na nic.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Dana Ruiz. Jedno „n”, dwa „r”? Nie, odwrotnie. Zawsze się mylę.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli budzik zostanie w biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Kupię nowy, ale ten ma w sobie moje dwanaście lat. Nowy nie będzie mnie lubił.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki! Czwarta piętnaście, słyszysz, budziku? Bez ciebie nie ruszam.", "zysk": "Dana wstanie na czwartą piętnaście i zdąży do zajezdni.", "strata": "Nic Cię to nie kosztuje, poza dwiema minutami kolejki.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Dana Ruiz: „Budzik działa. Sąsiad się obudził, ja też. Mówię, bo nikt tak nie dziękuje jak człowiek, któremu ktoś oddał budzik.”"}}, {"akcja": "odmow", "reakcja": "Co? Ale przecież to mój budzik! No dobra, przyniosę kogoś z zajezdni, żeby potwierdził.", "zysk": "Budzik zostaje w biurze do potwierdzenia.", "strata": "Dana nie wstanie na czwartą i spóźni się do pracy, a w zajezdni nikt jej nie wybroni.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Dana Ruiz: „Spóźniłam się do pracy o czterdzieści minut. Przełożony zapisał, a ja zapisałam sobie, że biuro też umie odmówić.”"}}], "sprite": "budzik", "face": null, "face2": null, "line": "11", "itemName": "Blaszany budzik z dwoma dzwonk", "inside": null}, {"id": "d4_iris", "dzien": 4, "postac": "Iris Bell, 56", "glos": "Cicho, uprzejmie, ze zdrobnieniami. Prosi o „drobną przysługę”, a groźbę podaje jak prognozę pogody.", "typ": "presja i łapówka", "rzecz": "Płaska paczka w szarym płótnie, przewiązana sznurkiem", "wnetrze": [{"sekret_id": "d4_blankiet_kasetka", "co_widac": "Pod płótnem leży kasetka na kłódkę, przez szparę widać brzeg paszportu z wyciętą stroną. Obok blankiet z numerem odbioru 0412 i dopisek „dla nocnej zmiany, bez wpisu”.", "co_z_tego_wynika": "To nie są papiery lokatorów, tylko dokumenty dla kogoś, kto chce zniknąć. Poprzednik przyjmował takie paczki bez wpisu."}], "wejscie": "Dobry wieczór. Iris Bell, zarządzam kamienicą przy Cooper Street dziewięć. Zgubiła mi się paczka w szarym płótnie, w szóstce, ostatnim kursem. To drobiazg, ale lokatorzy czekają na nią do rana.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta paczka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Płaska, w szarym płótnie, związana sznurkiem. W środku niewielka kasetka na kłódkę.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie została?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W szóstce, ostatnim kursem, na półce nad siedzeniem. Zawsze tak kładę i zawsze pamiętam. Wczoraj nie.", "mina": "neutralna"}, {"tekst": "Co jest w kasetce?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Papiery lokatorów. Pokwitowania, drobne rozliczenia. Nic ciekawego.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Kim są ci lokatorzy?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dwadzieścia rodzin z kamienicy. Zbieram od nich zaliczki na remont i trzymam ich dokumenty, żeby się nie zgubiły. Ironia, prawda?", "mina": "mowi"}, {"tekst": "Czemu paczka jedzie tramwajem, a nie pocztą?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo lokatorzy odbierają o różnych godzinach, a tramwaj to najtańszy goniec.", "mina": "neutralna"}, {"tekst": "Czemu tej paczki nie może odebrać nikt inny?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo to moje. Nie lubię, jak ktoś grzebie w rzeczach lokatorów.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Zależy Ci na czasie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Najlepiej dziś. Nie lubię naciskać, ale lokatorzy lubią spać spokojnie.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Oczywiście, Iris Bell. I chciałabym zostawić drobną kopertę za fatygę, nie jako opłatę, tylko jako wyraz uznania. Sto dwadzieścia dolarów.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli paczka wyjdzie tylko z wpisem do księgi?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy poczekam. Papier lubi czekać, ludzie nie.", "mina": "neutralna"}, {"tekst": "W kasetce widać brzeg paszportu z wyciętą stroną. Co to jest?", "ton": "niewygodne", "wymaga": "d4_blankiet_kasetka", "odpowiedz": "Jutro o świcie ktoś jedzie. Jeśli paczka zostanie, nie pojedzie. Nie mówię tego, żeby naciskać, tylko żeby wiedział ktoś, czyje to papiery.", "mina": "emocja"}]}], "decyzje": [{"akcja": "rejestr", "etykieta": "Wydaj paczkę i zapisz w księdze", "reakcja": "Dziękuję. Pełny wpis, jak widzę. Bardzo oficjalnie, ale dobrze.", "zysk": "Księga jest czysta: paczka wpisana jako znaleziona i wydana Iris Bell.", "strata": "Iris wie, że ktoś w biurze zapisuje, i traci poczucie, że ma tu swojego człowieka.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Paczka dotarła. Dziękuję za pełny wpis. Poprzedni współpracownik nie był tak skrupulatny, może to i lepiej. Ja lubię wiedzieć, z kim pracuję. — I. Bell"}}, {"akcja": "koperta", "etykieta": "Wydaj i przyjmij kopertę 120 $ (bez wpisu)", "kasa": 120, "reakcja": "Miło. Rozumiemy się bez zbędnych słów.", "zysk": "Dostajesz 120 dolarów, prawie cały tygodniowy czynsz.", "strata": "Paczka wychodzi bez wpisu, jak za poprzednika, a Ty zaczynasz być w układzie Iris.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dziękuję za dyskrecję. W przyszłym tygodniu przyniosę jeszcze jedną paczuszkę. Będzie bardzo drobna. — I. Bell"}}, {"akcja": "odmow_zglos", "etykieta": "Odmów i zgłoś paczkę do kontroli", "reakcja": "Rozumiem. Takie jest prawo, nie przeczę. Proszę tylko zapisać, że miałam dobre intencje. Rano zajmą się mną inni, mniej cierpliwi. To nie groźba, tylko prognoza pogody.", "zysk": "Paczka leży w depozycie: nikt jej nie dostaje i nikt nie zarzuci Ci układu.", "strata": "Iris traci cierpliwość, a ktoś, kto miał jutro jechać, może nie pojechać.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Iris Bell: „Rano zgłosiło się do mnie dwóch lokatorów, pytali, gdzie są ich dokumenty. Powiedziałam, że biuro zatrzymało je z powodu procedury. Nie byli zadowoleni.”"}}], "sprite": "paczka_plotno", "face": "dama", "face2": null, "line": "6", "itemName": "paczka w płótnie", "inside": {"img": "W2", "x": 0.66, "y": 0.35}}, {"id": "d5_noah", "dzien": 5, "postac": "Noah Reyes, 42", "glos": "Spokojnie, powtarza po swojemu: „Czyli: …”. Kiedy coś pomija, mówi: „To moje zmartwienie.”", "typ": "uczciwy, pomija zamiast kłamać", "rzecz": "Czarny służbowy notes na spirali, wgnieciony z lewej strony", "wnetrze": [{"sekret_id": "d5_notes_ulotki", "co_widac": "W notesie notatka: „E.D. zamówił ulotki z twarzą żony w czwartek o 22:15. Zgłoszenie zaginięcia złożył o 23:30.”", "co_z_tego_wynika": "Evan zamówił ulotki wcześniej, niż zgłosił zaginięcie. Wiedział, że żona odeszła."}], "wejscie": "Noah Reyes, komisariat przy Rynku. Zgubiłem służbowy notes, czarny, na spirali, w jedenastce. Mam w nim zeznanie Evana Doyle'a w sprawie jego żony Mai i potrzebuję go na dziś.", "wejscie_jesli": {"d3_maz_i_siostra:wydaj_evan": "Noah Reyes, komisariat. Zgubiłem służbowy notes, czarny, na spirali, w jedenastce. Są w nim zeznania Doyle'a. Wiem, że telefon jego żony wydano jemu, więc muszę wiedzieć, co z nim zrobił.", "d3_maz_i_siostra:wez_100_evan": "Noah Reyes, komisariat. Zgubiłem służbowy notes, czarny, na spirali, w jedenastce. Są w nim zeznania Doyle'a. Wiem, że telefon jego żony wydano jemu, więc muszę wiedzieć, co z nim zrobił.", "d3_maz_i_siostra:wydaj_lena": "Noah Reyes, komisariat. Zgubiłem służbowy notes, czarny, na spirali, w jedenastce. Telefon Mai Doyle wydano jej siostrze, nie mężowi. Doyle jest wściekły i dzwoni do mnie co godzinę.", "d3_maz_i_siostra:zatrzymaj": "Noah Reyes, komisariat. Zgubiłem służbowy notes, czarny, na spirali, w jedenastce. Telefon Mai Doyle został u was. Doyle dzwoni do mnie co godzinę, a ja nie wiem, co mu odpowiadać."}, "tury": [{"pytania": [{"tekst": "Jak wygląda ten notes?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, na spirali, wgnieciony z lewej strony. Zawsze kładę go równo z krawędzią blatu.", "mina": "mowi"}, {"tekst": "Gdzie go zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, po dyżurze, na siedzeniu obok. Rozmawiałem z kierowcą i wysiadłem bez niego.", "mina": "neutralna"}, {"tekst": "Co jest w tym notesie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Notatki ze służby. Nic, co wolno komuś pokazywać.", "mina": "neutralna"}, {"tekst": "W notesie jest zapis: ulotki Evana, czwartek 22:15. Co to znaczy?", "ton": "niewygodne", "wymaga": "d5_notes_ulotki", "odpowiedz": "Że Doyle zamówił ulotki z twarzą żony godzinę i kwadrans przed zgłoszeniem. Zgłosił o 23:30. Może zbieg okoliczności, nie chcę tego rozstrzygać przy okienku. To moje zmartwienie.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Jak idzie sprawa Mai Doyle?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Powoli. Mąż zgłosił zaginięcie w czwartek, siostra twierdzi, że nic nie wie. Za mało, żeby ruszyć z miejsca.", "mina": "mowi"}, {"tekst": "Do kiedy sprawa jest otwarta?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Zgłoszenie rozstrzyga się najpóźniej dwudziestego drugiego. Potem idzie do wydziału, a tam nikt nie pyta o jej zgodę.", "mina": "mowi"}, {"tekst": "Co Evan mówi o telefonie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Że chce go mieć. Resztę pomija.", "mina": "neutralna"}, {"tekst": "Evan dostał telefon. Co z nim zrobił?", "ton": "niewygodne", "wymaga": "d3_maz_i_siostra:wydaj_evan|d3_maz_i_siostra:wez_100_evan", "odpowiedz": "Przyniósł mi go rano. Zablokowany kodem, którego jakoby nie zna. Mówi, że żona nigdy nie miała kodu. To mi nie pasuje.", "mina": "neutralna"}, {"tekst": "Telefon dostała Lena. Co na to Evan?", "ton": "niewygodne", "wymaga": "d3_maz_i_siostra:wydaj_lena", "odpowiedz": "Dzwoni co godzinę, że siostra coś ukrywa. Lena twierdzi, że telefon jest u niej bezpieczny. Obie wersje chcę sprawdzić.", "mina": "neutralna"}, {"tekst": "Telefon został w biurze. Co na to Evan?", "ton": "niewygodne", "wymaga": "d3_maz_i_siostra:zatrzymaj", "odpowiedz": "Dzwoni co godzinę. Mówię, że sprawa jest u mnie, nie mówię, że telefon jest u was. Niech czeka.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Można jakoś pomóc w tej sprawie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Jak coś będzie nietypowe, zapisz godzinę i powiedz mi. Najlepiej zanim zapyta ktoś inny.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Noah Reyes, N i R. Dwa egzemplarze, jeden dla Ciebie.", "mina": "neutralna"}, {"tekst": "Czemu sam jeździsz nocnym tramwajem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wracam z dyżuru, mieszkam na końcu jedenastki. Czasem po drodze trafia się sprawa.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Czyli: notes wraca. Jak będę potrzebował kogoś, kto zapisuje godziny, będę wiedział, gdzie szukać.", "zysk": "Noah ma notes i wie, że biuro oddaje to, co należy.", "strata": "Noah dopytuje o telefon i będzie wracał z pytaniami o Maję.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Noah Reyes: „Notes odebrany. Czyli: dziękuję. Proszę zapisywać godziny wydań telefonu Mai. To na wszelki wypadek.”"}}, {"akcja": "zadzwon", "etykieta": "Zadzwoń na komisariat, żeby potwierdzili", "reakcja": "Dzwoń. Numer dwanaście. Dyżurny potwierdzi, że notes jest mój.", "zysk": "Masz potwierdzenie z komisariatu, że to notes Noaha.", "strata": "Noah wie, że sprawdzasz nawet policję, i nie lubi czekać.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dyżurny z komisariatu potwierdził: notes N. Reyesa. Odebrany. Dziękujemy za czujność, choć jedna minuta wystarczyłaby. — Komisariat przy Rynku"}}], "sprite": "notes", "face": null, "face2": null, "line": "4", "itemName": "notes", "inside": null}, {"id": "d5_victor", "dzien": 5, "postac": "Victor Crane, 51", "glos": "Krótkie pytania, zero rozmów o pogodzie. Zawsze: „Kto może to podpisać?” Pokwitowanie w dwóch egzemplarzach.", "typ": "kontroler jawny", "rzecz": "Szara teczka kontroli zapinana na klamrę", "wnetrze": [{"sekret_id": "d5_wykaz_dopisany", "co_widac": "W teczce wykaz wydań z poprzedniej zmiany. Pozycje „prawa rękawiczka T. Ward” i „paczka bez wpisu” dopisano innym tuszem. Obok parafa V.C.", "co_z_tego_wynika": "Victor dopisał obie pozycje sam, po fakcie. Wie o wydaniach poprzednika od dawna."}], "wejscie": "Victor Crane, inspekcja przewozów. Zgubiłem teczkę kontroli, szarą, na klamrę, w szóstce. O siódmej rano rozliczam tydzień z księgą wydań. Czy ktoś ją tu oddał?", "wejscie_jesli": {"d4_iris:koperta": "Victor Crane, inspekcja przewozów. Zgubiłem teczkę kontroli, szarą, na klamrę, w szóstce. O siódmej rozliczam tydzień z księgą wydań, a w tym tygodniu brakuje w niej jednej paczki. Czy ktoś oddał teczkę?", "d4_iris:odmow_zglos": "Victor Crane, inspekcja przewozów. Zgubiłem teczkę kontroli, szarą, na klamrę, w szóstce. Rozliczam tydzień z księgą wydań, a u was w depozycie leży paczka, którą chcę zobaczyć. Czy ktoś oddał teczkę?"}, "tury": [{"pytania": [{"tekst": "Jak wygląda ta teczka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szary skaj, klamra z przodu, naklejka inspekcji na rogu. W środku formularze i pieczątka.", "mina": "mowi"}, {"tekst": "Gdzie ją zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W szóstce, o 4:10, na siedzeniu obok. Wysiadłem przy zajezdni bez niej. To mi się nie zdarza.", "mina": "neutralna"}, {"tekst": "Czemu inspektor sam jeździ nocnym tramwajem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo kontrola ma sprawdzać, jak jest, a nie jak ma być. A w nocy jest zawsze inaczej niż w grafikach.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co kontrolujesz w tym biurze?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czy księga wydań zgadza się z magazynem i z kwitami. Wpis, kwit, podpis. Czasem brakuje któregoś.", "mina": "mowi"}, {"tekst": "Po czym poznasz, że teczka jest Twoja?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na klapie są inicjały V.C. i pieczątka inspekcji, numer czterdzieści siedem.", "mina": "neutralna"}, {"tekst": "Czy ostatnie wydania w tym biurze były poprawne?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie wszystkie. Jedna paczka bez wpisu i jedna rękawiczka bez księgi. Dlatego potrzebuję teczki.", "mina": "neutralna"}, {"tekst": "W teczce jest wykaz z dopisanymi pozycjami i parafą V.C. Kto je dopisał?", "ton": "niewygodne", "wymaga": "d5_wykaz_dopisany", "odpowiedz": "Ja. Tydzień po odejściu poprzednika, z jego własnych słów. Nie mam na to dowodu. To niezgodne z regulaminem, więc proszę tego nie powtarzać.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co będzie, jeśli teczki nie będzie rano?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Audyt przesunie się o tydzień. W tym czasie ktoś zdąży poprawić księgę, a tego nie chcę.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Victor Crane. Dwa egzemplarze pokwitowania, jeden zostaje w księdze. Zawsze.", "mina": "neutralna"}, {"tekst": "Czy ktoś spoza inspekcji może widzieć zawartość teczki?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. Jeśli ktoś zajrzał, chcę znać nazwisko.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wykaz_paczke", "etykieta": "Wydaj teczkę i wykaż paczkę 0412", "reakcja": "Dziękuję. Dwa egzemplarze pokwitowania. Wpis: paczka 0412 w depozycie biura, dla właściciela.", "zysk": "Księga i magazyn się zgadzają, audyt idzie bez opóźnień.", "strata": "Paczka ma numer i będzie miała właściciela. Ktoś po nią przyjdzie, a Iris dowie się, kto ją wystawił.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Paczka 0412 zapisana, protokół w dwóch egzemplarzach. Do piątku proszę o dokumenty z poprzednich zmian. — V. Crane"}}, {"akcja": "spis_bez_paczki", "etykieta": "Wydaj teczkę, potwierdź spis bez paczki", "reakcja": "Spis zgodny. Dwa egzemplarze. Dziwne, że tydzień zgadza się co do sztuki.", "zysk": "Dziś spokój: Victor zamyka tydzień, a Iris i jej klient nie są wystawieni.", "strata": "W spisie brakuje paczki, a Victor zostaje z podejrzeniem, że coś przechodzi obok księgi.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Spis przyjęty. Tydzień zgodny co do sztuki, co mnie niepokoi. Wrócę do tej księgi. — V. Crane"}}], "sprite": "teczka", "face": "inspektor", "face2": null, "line": "6", "itemName": "teczka kontroli", "inside": {"img": "W17", "x": 0.66, "y": 0.32}}, {"id": "d5_gus", "dzien": 5, "postac": "Gus Pell, 55", "glos": "Cicho, grzecznie ze strachu, rozgląda się. Zaczyna zdania od „tylko”.", "typ": "uczciwy-wstydliwy i łapówka", "rzecz": "Brązowy, wytarty portfel na zatrzask", "wnetrze": [{"sekret_id": "d5_dwa_dowody", "co_widac": "W portfelu są dwa dowody osobiste: Gustaw Pell i August Ferro, z tym samym zdjęciem. Do tego zdjęcie dziewczynki i bilet w jedną stronę na jutro, 5:40.", "co_z_tego_wynika": "Gus ma dwie tożsamości i jutro wyjeżdża. Prawdopodobnie jest klientem Skrytki."}, {"sekret_id": "d5_gotowka_400", "co_widac": "Za zdjęciem dziewczynki, w przegródce, zwinięte banknoty: cztery stówki.", "co_z_tego_wynika": "Gus ma 400 dolarów na wyjazd. To wszystko, co ma. Mówił o dwudziestu."}], "wejscie": "Dobry wieczór. Wiem, jak wyglądam: szlafrok pod płaszczem, bo wyszedłem z domu w pośpiechu. Zgubiłem portfel w jedenastce, brązowy, wytarty. Jutro o 5:40 jadę stąd jedenastką i bez portfela nie wsiądę.", "wejscie_jesli": {"d5_victor:wykaz_paczke": "Dobry wieczór. Gus Pell. Przed chwilą inspektor pytał o paczkę 0412, a ja powiedziałem, że to moja. Przyszedłem po portfel, brązowy, wytarty, z jedenastki. Jutro o 5:40 jadę stąd i bez niego nie ruszę."}, "tury": [{"pytania": [{"tekst": "Jak wygląda ten portfel?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowy, wytarty, na zatrzask. Mam go od jedenastu lat, wygiął się na moją kieszeń.", "mina": "mowi"}, {"tekst": "Co w nim jest?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Prawo jazdy, dwadzieścia dolarów i zdjęcie córki. Nic więcej, tylko tyle.", "mina": "klamie"}, {"tekst": "Czemu o pierwszej w nocy jesteś w szlafroku?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo pokłóciłem się w domu i wyszedłem bez myślenia. Z żoną, z teściową, z obiema. O rodzinie nie rozmawiajmy.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Jak się nazywasz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Gustaw Pell. Gus. Tylko proszę nie zapisywać, że byłem w szlafroku.", "mina": "mowi"}, {"tekst": "Gdzie mieszkasz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Mill Street dwanaście. Zaraz, nie, piętnaście. Dwanaście to brat, ale on się wyprowadził.", "mina": "klamie"}, {"tekst": "Z kim dokładnie się pokłóciłeś?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Z żoną. Nie, z teściową. Z obiema. Tylko że naprawdę nie chcę o tym mówić.", "mina": "neutralna"}, {"tekst": "W portfelu są dwa dowody: Pell i Ferro. Który jest Twój?", "ton": "niewygodne", "wymaga": "d5_dwa_dowody", "odpowiedz": "Dwa? To się da wytłumaczyć. Jeden po dziadku. Który mój, nie powiem, bo to się źle kończy.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Dokąd jedziesz jutro?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Jedenastką, o 5:40, dalej już nie powiem. Daleko. Tylko proszę nie pytać gdzie.", "mina": "emocja"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Podpiszę. G. Samo G, wystarczy? Tylko żeby nie było pytań o resztę.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli portfel zostanie w biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy ktoś pomyśli, że zniknąłem. I będzie miał rację.", "mina": "emocja"}, {"tekst": "Za zdjęciem są cztery stówki. Mówiłeś o dwudziestu.", "ton": "niewygodne", "wymaga": "d5_gotowka_400", "odpowiedz": "Bo to nie pieniądze na życie, tylko na wyjazd. Wszystko, co mam. Proszę nikomu nie mówić, że je widziałem.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Zapomnijmy, że byłem w szlafroku.", "zysk": "Gus wychodzi z portfelem i dwoma dowodami, jutro jedzie o 5:40.", "strata": "Nie wiesz, który dowód jest prawdziwy, a w księdze zostaje tylko wpis „Pell”.", "echo": {"za_dni": 4, "forma": "list", "tekst": "Pocztówka z miasta, którego nazwy nie znam: „Dziękuję za portfel. Pell już nie istnieje. — G.”"}}, {"akcja": "odmow", "reakcja": "Rozumiem. Wrócę z kimś, kto ma wszystkie dokumenty. Tylko proszę nie dzwonić nigdzie.", "zysk": "Portfel zostaje w biurze razem z dwoma dowodami.", "strata": "Gus nie wsiądzie jutro o 5:40 i wraca do domu w szlafroku, a jego sprawa jest otwarta.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Do biura zadzwoniła żona Gusa Pella: mąż zniknął, zostawił tylko szlafrok i trzy dolary. Pyta, czy ktoś go widział. Zapisano: brak informacji."}}, {"akcja": "zadzwon", "etykieta": "Zadzwoń po dyżurnego policjanta", "reakcja": "Proszę, bez policji. To nie jest sprawa dla policji.", "zysk": "Dyżurny przyjmie zgłoszenie, a oba dowody trafią do protokołu.", "strata": "Gus ucieknie, zanim ktoś przyjdzie, a w protokole zostanie pusta rubryka „właściciel”.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Z komisariatu: portfel z dwoma dowodami wpisano do ewidencji, właściciel się nie zgłosił. Dziękujemy za czujność. — N. Reyes"}}, {"akcja": "wez_400_gus", "etykieta": "Wydaj portfel, ale zatrzymaj 400 $ z przegródki", "kasa": 400, "reakcja": "Dziękuję. Zaraz, a... nie, nic. Do widzenia.", "zysk": "Dostajesz 400 dolarów, prawie trzy czynsze, a Gus nie ma jak się poskarżyć.", "strata": "Gus jedzie jutro bez grosza, z dwoma dowodami, i nikt mu nie pomoże po drodze.", "echo": {"za_dni": 4, "forma": "list", "tekst": "Pocztówka z dworca: „Dojechałem. Przegródka była pusta, ktoś wiedział, gdzie szukać. Śpię na ławce. Pell nie istnieje. Ja prawie też. — G.”"}}, {"akcja": "przywlaszcz", "etykieta": "Wydaj portfel, ale zatrzymaj 70 $", "kasa": 70, "reakcja": "Dokumenty są, zdjęcie jest. Pieniędzy nie ma. Nie będę pytał, nie mam kiedy. Pociąg o 5:40.", "zysk": "+70 $ z portfela, których nikt nie policzył.", "strata": "Gus jedzie na swój pociąg bez grosza, a ty robisz to, co Sam robił z dobrego serca, tylko w drugą stronę.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dojechałem. Bez pieniędzy, ale dojechałem, zdjęcie dziewczynki mam przy sercu. W portfelu było siedemdziesiąt dolarów. Pomyślałem, że ktoś po drodze też ich potrzebował. Gus"}}], "sprite": "portfel", "face": null, "face2": null, "line": "6", "itemName": "Brązowy", "inside": null}, {"id": "d6_ada", "dzien": 6, "postac": "Ada Vale, 10", "glos": "Dosłownie, jak dziecko. Liczy kroki i kamienie. Kiedy się boi, mówi szeptem.", "typ": "uczciwa, wie za dużo", "rzecz": "Szary pluszowy królik z uchem doszytym czerwoną nitką", "wnetrze": [], "wejscie": "Dzień dobry, jestem Ada, mam dziesięć lat. Znalazłam królika przy pętli szóstki, trzy kroki od słupka. Chcę kwit, że zrobiłam to dobrze, bo mama mówi, że bez kwitu nie wiadomo.", "wejscie_jesli": {"d1_rosa:wydaj": "Dzień dobry, jestem Ada, córka Rosy z pralni. Mama mówi, że dostała od was całą wypłatę. Znalazłam królika przy pętli szóstki, trzy kroki od słupka. Chcę kwit, że zrobiłam to dobrze.", "d1_rosa:odmow": "Dzień dobry, jestem Ada, córka Rosy z pralni. Mama dostała mniej wypłaty, ale mówi, że to nie wasza wina. Znalazłam królika przy pętli szóstki, trzy kroki od słupka. Chcę kwit, że zrobiłam to dobrze.", "d1_rosa:wez_20": "Dzień dobry, jestem Ada, córka Rosy z pralni. Mama płakała w kuchni, bo w kopercie brakowało pieniędzy. Nie wiem kto wziął. Znalazłam królika przy pętli szóstki. Chcę kwit, że zrobiłam to dobrze."}, "tury": [{"pytania": [{"tekst": "Jak wygląda królik?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szary, z jednym uchem doszytym czerwoną nitką. Ma dziurkę w nosie, jakby ktoś go przeziębił.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie go znalazłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na ławce przy pętli szóstki, trzy kroki od słupka. Siedział sam, jakby na kogoś czekał.", "mina": "mowi"}, {"tekst": "Czemu sama jesteś w nocy na pętli?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo mama pracuje na nocnej zmianie, a ja się nudzę. Chodzę po pętli i liczę. Wczoraj były sto dwa kamienie.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Po co Ci kwit?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Żeby wszyscy wiedzieli, że znalazłam, a nie wzięłam. Pani w szkole mówi, że to jest różnica.", "mina": "mowi"}, {"tekst": "Gdzie mieszkasz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na Cooper Street dziewięć, na drugim piętrze. Ale pani Iris prosiła, żeby nie mówić. No, powiedziałam.", "mina": "mowi"}, {"tekst": "Czemu nie możesz podać adresu?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Szeptem: bo pani Iris zabiera mieszkanie, jak ktoś gada. Mama tak mówi, jak myśli, że nie słyszę.", "mina": "emocja"}, {"tekst": "Na odcinku w puszce jest numer z bloczka Iris. Znasz tę puszkę?", "ton": "niewygodne", "wymaga": "d6_puszka_odcinek", "odpowiedz": "Widziałam taką u pani Iris w kuchni, nad czajnikiem. Wszystkie puszki miały dno, które się rusza. Nikomu nie mów, że mówiłam.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz z królikiem?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Oddam. Jak ktoś po niego przyjdzie, niech wie, że miał bezpiecznie.", "mina": "mowi"}, {"tekst": "Co ma być na kwicie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Że Ada Vale, dziesięć lat, znalazła królika. Dużymi literami, bo pani w szkole czyta tylko duże.", "mina": "mowi"}, {"tekst": "Co powie Twoja mama?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Że nic nie wolno brać, ale trzeba oddawać. Mama mówi dwie rzeczy naraz, bo musi.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wpisz_w_biurze", "etykieta": "Wpisz Adę jako znalazczynię, dane zostają w biurze", "reakcja": "Mam kwit! Pokażę go pani w szkole. Napisali moje nazwisko dużymi literami.", "zysk": "Ada ma dowód, że zrobiła dobrze, i bardzo się cieszy.", "strata": "Biuro ma jej adres w księdze, a Iris jest administratorką tej kamienicy i do księgi zagląda.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Iris Bell: „Słyszałam, że moja mała lokatorka została wpisana w księdze jako znalazczyni. Jak miło z jej strony. Dobrze wiedzieć, kto u kogo bywa.”"}}, {"akcja": "list_przewozowy", "etykieta": "Przekaż zgłoszenie razem z listem przewozowym", "reakcja": "A to znaczy, że jak ktoś po niego przyjdzie, to dowie się, że to ja? To chyba dobrze.", "zysk": "Królik i puszka idą oficjalnym obiegiem, a Urząd dostaje papier z numerem.", "strata": "Dane Ady krążą po urzędach, a Iris jako administratorka kamienicy je zobaczy.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Rosa: „Dostałyśmy pismo z Urzędu z nazwiskiem Ady. Iris powiedziała, że to formalność, ale patrzyła na mnie jak na gołębia na parapecie. Za tydzień może być wypowiedzenie. — Rosa”"}}, {"akcja": "wydaj_bez_wpisu", "etykieta": "Daj Adzie karteczkę „dobrze zrobiłaś”, bez wpisu", "reakcja": "O! Własnoręcznie podpisana. Pokażę mamie i pani w szkole. Dziękuję.", "zysk": "Ada ma kwit, a nikt nie zna jej adresu.", "strata": "Królik leży w biurze bez wpisu, a Ty robisz to samo, co poprzednik z rękawiczką.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Ada Vale: „Pokazałam karteczkę pani w szkole. Powiedziała, że to nie jest oficjalny kwit, ale że jest ładnie napisany. Wzięła go do gabloty.”"}}], "sprite": "krolik", "face": null, "face2": null, "line": "6", "itemName": "pluszowy królik", "inside": null}, {"id": "d6_leo", "dzien": 6, "postac": "Leo Marsh, 46", "glos": "Mówi godzinami i przystankami. Żartuje z żony. Patrzy na pusty nadgarstek.", "typ": "uczciwy, milczy o puszce", "rzecz": "Mosiężny zegarek kieszonkowy z łańcuszkiem", "wnetrze": [{"sekret_id": "d6_zegarek_list", "co_widac": "Pod wieczkiem zegarka wsunięta karteczka z wykazu zmiany. Dopisek długopisem: „+ puszka (b.n.)”.", "co_z_tego_wynika": "Leo przyjął puszkę bez nadawcy i dopisał ją do wykazu, żeby nie mieć kłopotów."}], "wejscie": "Dobry wieczór. Leo Marsh, konduktor szóstki. Zgubiłem zegarek kieszonkowy, mosiężny, z łańcuszkiem. Bez niego kursów nie pilnuję, a bez kursów nie ma mnie w robocie. Wiem, bo spojrzałem na nadgarstek, a tam nic.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten zegarek?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Mosiądz, łańcuszek, na wieczku grawer „za trzydzieści lat”. Teść mi dał. Żona mówi, że za trzydzieści lat to ja nie będę wiedział, która godzina.", "mina": "mowi"}, {"tekst": "Kiedy go zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "O 22:47, na pętli. Wiem, bo spojrzałem, żeby sprawdzić godzinę, i odłożyłem na ławkę.", "mina": "neutralna"}, {"tekst": "Czemu nosisz zegarek, skoro masz telefon?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo telefon pokazuje godzinę, a zegarek ją mierzy. To nie to samo. Poza tym zegarek nie dzwoni mi o drugiej w nocy.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co jeszcze masz w kieszeni?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Bilety kontrolne, długopis i kartka z wykazem zmiany. Nic ciekawego.", "mina": "mowi"}, {"tekst": "Czemu zegarek jest cięższy, niż wygląda?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo to solidny mosiądz, nie żadna chińszczyzna. Dziadek mojej żony pracował w zajezdni, ten zegarek przeżył trzech szefów.", "mina": "mowi"}, {"tekst": "Co wiozłeś ostatnim kursem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Ludzi, dwie torby i walizkę. Normalny kurs.", "mina": "klamie"}, {"tekst": "Pod wieczkiem jest dopisek „+ puszka (b.n.)”. Jaka puszka?", "ton": "niewygodne", "wymaga": "d6_zegarek_list", "odpowiedz": "Ktoś mi ją wsunął pod ławkę, bez nadawcy, więc dopisałem do wykazu, żeby nie było kłopotu. Z tym się nie pytam, kto ma to odebrać.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Ile masz jeszcze kursów dziś?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dwa. Jak wrócę z zegarkiem, to oba na czas. Bez niego jeden na pewno spóźniony.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Leo Marsh. Podpis mam jak przystanek: krótki i na wprost.", "mina": "neutralna"}, {"tekst": "Czy ktoś Cię prosił, żebyś milczał?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. Nikt nikogo o nic nie prosi. Po prostu wiem, że jak coś jedzie pod ławką, to lepiej nie pytać.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki. O 22:47 nie spojrzę już na pusty nadgarstek. Żona będzie zadowolona, jak jej powiem.", "zysk": "Leo odzyskuje zegarek i jedzie następne kursy punktualnie.", "strata": "Puszka bez nadawcy zostaje w jego wykazie bez wyjaśnienia.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Leo Marsh: „Zegarek chodzi równo. Żona powiedziała, że przez trzy dni byłem człowiekiem bez czasu. Przepraszam, że tyle mówiłem o godzinach.”"}}, {"akcja": "zatrzymaj", "etykieta": "Zatrzymaj zegarek do wyjaśnienia puszki", "reakcja": "Co? To nie fair. Dobrze, wrócę. Ale kursy poczekają na mnie, nie na odwrót.", "zysk": "Zegarek leży w biurze, a Ty możesz dopytać Leo o puszkę przy następnej wizycie.", "strata": "Leo jedzie bez zegarka i może spóźnić dwa kursy.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Leo Marsh: „Spóźniłem się o cztery minuty na ostatnim kursie. Szef zapisał. Nie mam żalu do zegarka, ale do czasu mam.”"}}, {"akcja": "wpisz_puszke", "etykieta": "Wydaj zegarek i dopisz puszkę do księgi", "reakcja": "Dopisujesz? No... jak trzeba, to trzeba. Tylko niech nikt nie myśli, że wiem, od kogo.", "zysk": "Puszka ma ślad w księdze: kiedyś ktoś może ją odnaleźć i powiązać z blankietem z dnia 4.", "strata": "Leo jest wystawiony: w księdze widać, że przyjął puszkę bez nadawcy.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Leo Marsh: „Ktoś pytał, skąd puszka w wykazie. Powiedziałem, że z księgi biura. Zrobiło się cicho. Może tak ma być.”"}}, {"akcja": "przywlaszcz", "etykieta": "Sprzedaj zegarek w lombardzie (90 $)", "kasa": 90, "reakcja": "Nie ma zegarka? Szóstka, 23:05 z Doków, zawsze go sprawdzałem. No cóż. Zdarza się.", "zysk": "+90 $ z lombardu przy Rynku.", "strata": "Leo traci zegarek po ojcu, a ty zostajesz z rzeczą, której nie ma w żadnym wpisie.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Szóstka, 23:05 z Doków. Patrzyłem dziś na nadgarstek i nic tam nie było. Ktoś mówił, że w lombardzie na Rynku wisi mosiężny zegarek na łańcuszku. Nie pytam. Zdarza się. Leo"}}], "sprite": "zegarek", "face": null, "face2": null, "line": "6", "itemName": "zegarek kieszonkowy", "inside": null}, {"id": "d7_kit", "dzien": 7, "postac": "Kit Navarro, 17", "glos": "Krótko, sarkastycznie, „serio”. Slang, ale bez przesady.", "typ": "uczciwy, boi się wylecieć", "rzecz": "Czarne słuchawki nauszne z naklejką kota w kasku", "wnetrze": [], "wejscie": "Cześć, Kit. Zgubiłem słuchawki w czwórce, takie nauszne, z kotem w kasku na muszli. Pracuję w kopiarni na Rynku i jak szef się dowie, że słuchałem muzyki przy ksero, to po mnie. Serio.", "tury": [{"pytania": [{"tekst": "Jak wyglądają te słuchawki?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarne, nauszne, taśma na lewej muszli. Naklejka z kotem w kasku, bo kot jedzie na rowerze. Serio, kupiłem ją za dolara.", "mina": "mowi"}, {"tekst": "Gdzie je zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, na siedzeniu przy oknie, jak wracałem z roboty. Usnąłem na pół minuty i wysiadłem bez nich.", "mina": "neutralna"}, {"tekst": "Czemu szef nie lubi słuchawek w pracy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo mówi, że ksero ma być słychać, a ja mam słyszeć klientów. Ja słyszę, tylko że z muzyką mniej boli.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Ile masz lat?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Siedemnaście. Pracuję na praktykach, za zgodą rodziców, tylko że nocą się nie powinno. Dlatego nikomu nie mówię.", "mina": "mowi"}, {"tekst": "Co robisz w kopiarni po nocach?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Ksero, laminowanie, bindowanie. Ulotki, plakaty, dyplomy. Dużo osób drukuje po nocach rzeczy, których nie chce drukować za dnia.", "mina": "mowi"}, {"tekst": "Pamiętasz jakieś zamówienie z zeszłego tygodnia?", "ton": "niewygodne", "wymaga": null, "ustawia": "d7_kit_ulotki", "odpowiedz": "W czwartek o 22:15 facet w szarym płaszczu zamówił ulotki z twarzą kobiety, tysiąc sztuk. Zapłacił gotówką. Powiedział, że to dla żony. Serio, dziwnie się uśmiechał.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co się stanie, jak szef się dowie o słuchawkach?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Zdejmie mi dziesięć dolarów z wypłaty i da pogadankę. Pogadankę przeżyję, dziesięć dolarów mniej już trudniej.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Kit Navarro, przez K i V na końcu. Zawsze wszyscy piszą Navaro.", "mina": "neutralna"}, {"tekst": "Dlaczego powiedziałeś mi o ulotkach?", "ton": "niewygodne", "wymaga": "d7_kit_ulotki", "odpowiedz": "Bo patrzyłeś na mnie tak, jakbyś naprawdę słuchał. Nikt tak nie robi. A poza tym ten facet był dziwny i chciałem to komuś powiedzieć.", "mina": "emocja"}, {"tekst": "Czy przesyłałby ktoś zamówienia z kopiarni dalej?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. Wszystko zostaje u nas, w segregatorze. Szef lubi segregatory bardziej niż ludzi.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki, serio. Kot jedzie dalej. A tamten facet... jak coś będę widział, to wam powiem.", "zysk": "Kit odzyskuje słuchawki i zostaje po Twojej stronie.", "strata": "To, co powiedział o ulotkach, nie zostaje nigdzie zapisane.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Kit Navarro: „Słuchawki grają. Szef nie zauważył. Ten w szarym płaszczu wrócił i zamówił kolejne tysiąc. Serio, zamówił. Powiedziałem mu, że maszyna się zepsuła.”"}}, {"akcja": "wydaj_i_zapisz", "etykieta": "Wydaj i zapisz jego zeznanie o ulotkach", "reakcja": "Zapisujesz? Serio? Okej, ale jak szef zobaczy moje nazwisko w księdze, to po mnie.", "zysk": "Zeznanie Kita o ulotkach jest w księdze: policjant może je potem sprawdzić.", "strata": "Kit zostaje świadkiem z nazwiskiem w księdze i może stracić pracę, jak szef się dowie.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Noah Reyes: „W księdze jest zeznanie praktykanta z kopiarni o ulotkach. Czyli: godzina 22:15 się potwierdza. Dziękuję, że to ktoś zapisał.”"}}, {"akcja": "odmow", "reakcja": "Co? Ale to moje! Serio. Dobra, przyniosę paragon, tylko że paragonu nie mam.", "zysk": "Słuchawki zostają w biurze do czasu dowodu, że są Kita.", "strata": "Kit wraca do roboty bez muzyki i prawdopodobnie bez chęci mówienia o czymkolwiek.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Kit Navarro: „Dziś w kopiarni było cicho. Ksero słychać, tylko że bez muzyki jest głośniej. Serio, nie lubię tej ciszy.”"}}], "sprite": "sluchawki", "face": null, "face2": null, "line": "11", "itemName": "słuchawki", "inside": null}, {"id": "d7_evan", "dzien": 7, "postac": "Evan Doyle, 37", "glos": "Grzecznie, pełnymi zdaniami, wraca do tego samego pytania. Poprawia mankiet, dziś wygnieciony do połowy.", "typ": "kłamca, zna godziny, o które nikt nie pytał", "rzecz": "Brązowe skórzane etui na klucze z zatrzaskiem", "wnetrze": [{"sekret_id": "d7_etui_klucze", "co_widac": "W etui kartonik z inicjałami M.D. i znakiem nieskończoności oraz dwa klucze. Jeden pasuje do zamka w drzwiach Doyle'ów, drugi jest mniejszy i z nieznanego zamka.", "co_z_tego_wynika": "Maya miała drugi klucz, do mieszkania, o którym Evan nie wie. Zostawiła klucze celowo."}], "wejscie": "Dobry wieczór. Evan Doyle, znowu. Zgubiły się klucze mojej żony, brązowe etui, zatrzask. Czy mógłby ktoś powiedzieć, którą linią przyjechały? Chciałbym je odebrać osobiście, tam, gdzie je zostawiła.", "wejscie_jesli": {"d3_maz_i_siostra:wez_100_evan": "Dobry wieczór. Evan Doyle. Znamy się już, więc krótko: klucze mojej żony, brązowe etui. Czy mógłby ktoś powiedzieć, którą linią przyjechały? Dogadaliśmy się już raz, więc chyba nie ma problemu.", "d3_maz_i_siostra:wydaj_lena": "Dobry wieczór. Evan Doyle. Telefon żony wydaliście jej siostrze i do tej pory go nie widziałem. Poproszę więc o klucze, brązowe etui. Którą linią przyjechały?"}, "tury": [{"pytania": [{"tekst": "Jak wygląda to etui?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowa skóra, zatrzask. W środku kartonik z inicjałami M.D. i znakiem nieskończoności. To jej.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy zostało?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce albo w jedenastce, nie wiem. Czy mógłby ktoś powiedzieć, którą linią przyjechało?", "mina": "neutralna"}, {"tekst": "Ile kluczy tam jest?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Jeden. Do naszego mieszkania. A może dwa, ona miała zapasowy.", "mina": "klamie"}, {"tekst": "W etui są dwa klucze. Czemu opisałeś jeden?", "ton": "niewygodne", "wymaga": "d7_etui_klucze", "odpowiedz": "Bo drugiego nie znam. Maya miała swoje sprawy. Czy ktoś może mi powiedzieć, który to klucz i do czego?", "mina": "emocja"}]}, {"pytania": [{"tekst": "Od kiedy szukasz żony?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Od czwartku. Zgłosiłem o 23:30, jak tylko zrozumiałem, że nie wraca.", "mina": "klamie"}, {"tekst": "Skąd chcesz znać linię?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo wtedy będę wiedział, gdzie ona wsiada. Stanę na pętli i poczekam. Chcę tylko porozmawiać.", "mina": "mowi"}, {"tekst": "Ulotki z jej twarzą zamówiłeś o 22:15. Godzinę przed zgłoszeniem.", "ton": "niewygodne", "wymaga": "d7_kit_ulotki|d5_notes_ulotki", "odpowiedz": "To... na wszelki wypadek. Zamówiłem je wcześniej, bo przeczuwałem. Czy to coś zmienia? Czy ktoś mi to zapisze?", "mina": "emocja"}, {"tekst": "Czy wcześniej usłyszałeś od Mai, że odchodzi?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. Skąd. Przecież to nie byłoby rozsądne, tak bez słowa.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Co zrobisz, jak ją znajdziesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Zabiorę ją do domu. Zrobię jej herbatę, jak zawsze. Reszta to nasza sprawa.", "mina": "mowi"}, {"tekst": "Czemu sam nie zgłosisz zaginięcia na policji?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Zgłosiłem. Powiedzieli, że dorosła osoba może wyjść z domu. Więc przychodzę tu.", "mina": "neutralna"}, {"tekst": "Czego Maya się boi?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Niczego. Ma wszystko, co trzeba. Dom, męża, spokój. Nie rozumiem pytania.", "mina": "klamie"}]}], "decyzje": [{"akcja": "powiedz_linie", "etykieta": "Powiedz, którą linią przyjechały klucze", "reakcja": "Czwórka. Dziękuję. Stanę na pętli i poczekam. Chcę tylko porozmawiać, naprawdę.", "zysk": "Evan dostaje, o co prosi, i przestaje naciskać na biuro.", "strata": "Evan zacznie stać na pętli czwórki, a Maya straci tam spokój.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Leo Marsh: „Na pętli czwórki stoi od wczoraj facet w płaszczu z termosem. Nie wsiada, tylko patrzy na każdego, kto wysiada. Ludzie schodzą mu z drogi.”"}}, {"akcja": "zatrzymaj_list", "etykieta": "Zatrzymaj etui, zaproponuj zapieczętowany list", "reakcja": "List? Dla niej? Dobrze, ale przecież ona go nie dostanie, prawda? Czy mógłby ktoś obiecać?", "zysk": "Zyskujesz czas: etui zostaje w biurze, a Evan może napisać do żony.", "strata": "Obiecujesz coś, czego nie możesz zagwarantować, bo Maya może nie przyjść.", "echo": {"za_dni": 4, "forma": "list", "tekst": "Evan Doyle: „Napisałem list i zostawiłem go przy okienku. Mam nadzieję, że ktoś go przekaże. Nie mam innego sposobu. — E.D.”"}}, {"akcja": "odmow", "reakcja": "Czyli nic. Rozumiem. Wrócę jutro, a pojutrze znów. Proszę zapisać, że pytałem.", "zysk": "Etui zostaje w biurze, a Evan nic nie wie o linii.", "strata": "Evan zostaje z niczym i wraca ostrzejszy.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Evan Doyle: „Wróciłem, jak obiecałem. Nikt mi nie chciał powiedzieć, gdzie są klucze. To rozumiem jako odmowę wobec męża. Zapisałem godzinę.”"}}], "sprite": "klucze", "face": "maz", "face2": null, "line": "11", "itemName": "etui na klucze", "inside": {"img": "W5", "x": 0.43, "y": 0.31}}, {"id": "d8_lena_i_nora", "dzien": 8, "postac": "Lena Brandt i Nora Vance", "glos": "Lena: szybko, urywa, „ale…”. Nora: po kolei, na palcach, „rzecz, osoba, skutek”.", "typ": "dwie prawdy o jednej torbie", "rzecz": "Szara torba narzędziowa z rozprutą podszewką", "ludzie": {"siostra": "Lena", "nora": "Nora"}, "wnetrze": [{"sekret_id": "d8_torba_kopia", "co_widac": "W rozprutej podszewce leży żółta kopia pokwitowania zaliczek z podpisem „I.” i kwotą 400 dolarów. Obok narzędzia: obcęgi, śrubokręt, miara.", "co_z_tego_wynika": "Kopia dowodzi, że Iris Bell przyjęła 400 dolarów od lokatorów. Maya schowała ją na wszelki wypadek."}], "wejscie": "Dobry wieczór. Lena Brandt, a to Nora Vance. Obie przyszłyśmy po tę samą torbę narzędziową, szarą, z rozprutą podszewką. Lena mówi, że to torba jej siostry. Nora, że jest w niej papier z kamienicy.", "wejscie_jesli": {"d3_maz_i_siostra:wydaj_evan": "Dobry wieczór. Lena Brandt, a to Nora Vance. Obie po tę samą torbę narzędziową, szarą, z rozprutą podszewką. Lena po tym, jak Evan przyszedł do niej z pretensjami, chce chociaż torbę siostry. Nora chce papieru z kamienicy."}, "tury": [{"pytania": [{"tekst": "Czyja jest ta torba?", "ton": "uprzejme", "kto": "siostra", "wymaga": null, "odpowiedz": "Mai, mojej siostry. Kupiłam jej ją na urodziny, narzędzia, dziwny prezent, wiem. Teraz to jedyna rzecz po niej, jaką mogę dotknąć.", "mina": "emocja"}, {"tekst": "Czego Nora szuka w tej torbie?", "ton": "rzeczowe", "kto": "nora", "wymaga": null, "odpowiedz": "Po kolei: rzecz, osoba, skutek. Papier z podszewki, kopia pokwitowania, rodzina Okoye. Bez niego nie mają dowodu wpłaty.", "mina": "mowi"}, {"tekst": "Po czym poznacie, że torba jest właśnie ta?", "ton": "niewygodne", "kto": "siostra", "wymaga": null, "odpowiedz": "Po obcęgach z żółtą izolacją i miarze z dopiskiem „M”. Ale... no właśnie. Nora też wie, co jest w środku.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Skąd Nora wie, że w podszewce jest papier?", "ton": "uprzejme", "kto": "nora", "wymaga": null, "odpowiedz": "Z wykazu mieszkańców. Numer pokwitowania jest w moim zeszycie, a kopię ktoś schował. Nie wiem kto. Chcę zobaczyć, czy się zgadza.", "mina": "mowi"}, {"tekst": "Czy Maya pracowała w tej kamienicy?", "ton": "rzeczowe", "kto": "siostra", "wymaga": null, "odpowiedz": "Pracowała jako elektryczka na Cooper Street dziewięć, na pierwszym piętrze. Ale... no tak, tam była Iris. Nie rozmawiałyśmy o tym.", "mina": "mowi"}, {"tekst": "Ile osób jest w tej sprawie?", "ton": "niewygodne", "kto": "nora", "wymaga": null, "odpowiedz": "Czternaście rodzin, czterysta dolarów każda, termin dwudziestego czwartego. Po kolei, bo inaczej się pogubię: dwie wpłaty, Okoye i jeszcze jedna.", "mina": "mowi"}, {"tekst": "W podszewce jest kopia z podpisem „I.” i kwotą 400 $. Czyja?", "ton": "niewygodne", "kto": "nora", "wymaga": "d8_torba_kopia", "odpowiedz": "Iris Bell, zarządczyni. To jej podpis, ja go znam z dwudziestu pokwitowań. Kopia dowodzi, że Okoye zapłacili. Oryginał ma Iris.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobicie z torbą, jak ją dostaniecie?", "ton": "uprzejme", "kto": "siostra", "wymaga": null, "odpowiedz": "Zabiorę ją do siebie, do mieszkania. Ale... jeśli Maya wróci, to wyda mi się, że torba jest jej. No, że jest jej.", "mina": "emocja"}, {"tekst": "Odbiór wymaga podpisu. Kto podpisze?", "ton": "rzeczowe", "kto": "nora", "wymaga": null, "odpowiedz": "Ja, jako przedstawicielka lokatorów, jeśli chodzi o kopię. Za torbę niech podpisze siostra. Dwie osoby, dwa podpisy.", "mina": "neutralna"}, {"tekst": "Czy któraś z Was ustąpi?", "ton": "niewygodne", "kto": "nora", "wymaga": null, "odpowiedz": "Ja nie, bo chodzi o czternaście rodzin. Lena pewnie też nie. Tak jest.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj_lenie_cala", "etykieta": "Wydaj Lenie całą torbę", "kto": "siostra", "reakcja": "Dziękuję. Mam coś po niej. A... Nora, przepraszam, ale to siostra.", "zysk": "Lena ma torbę siostry i spokojniej śpi.", "strata": "Nora traci dowód wpłaty rodziny Okoye, a bez żółtej kopii mają tylko jej słowo.", "echo": {"za_dni": 4, "forma": "gosc", "tekst": "Nora Vance: „Po kolei: kopia poszła z torbą do siostry Mai. Okoye znowu są bez dowodu. Wiem, że to nie wasza złość, tylko wybór. Ale wybór ma koszt.”"}}, {"akcja": "kopia_osobno", "etykieta": "Zasłoń dane, zrób kopię osobno za zgodą obu", "kto": "nora", "reakcja": "Zgoda. Po kolei: kopia zasłonięta, torba dla Leny, dokument zostaje w biurze. Nie lubię tego, ale dobrze.", "zysk": "Dowód zostaje w biurze, a Lena dostaje torbę, obie strony się zgodziły.", "strata": "Zajmuje to całą wizytę, a zasłonięte dane osłabiają dowód.", "echo": {"za_dni": 4, "forma": "gosc", "tekst": "Nora Vance: „Kopia z zasłoniętymi nazwiskami leży u was. To mało, ale to jest dowód. Jak będzie trzeba, wrócę po numer pokwitowania.”"}}, {"akcja": "odmow", "reakcja": "Nic z tego? Torba leży w biurze? No to co, mamy czekać? Ale... dobrze.", "zysk": "Torba zostaje w biurze, nikt jej nie dostaje i nikt nie ma pretensji o stronniczość.", "strata": "Lena nie ma nic po siostrze, a Nora nie ma kopii. Obie odchodzą z pustymi rękami.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Lena Brandt: „Torba leży u was, a ja o niej myślę każdą noc. Wiem, że przepisy. Ale to jej torba, a ona nie ma nic innego, co by o niej przypominało.”"}}], "sprite": "torba_narzedzia", "face": "siostra", "face2": {"siostra": "siostra", "nora": null}, "line": "4", "itemName": "torba narzędziowa", "inside": {"img": "W6", "x": 0.37, "y": 0.6}}, {"id": "d8_bree", "dzien": 8, "postac": "Bree Halm, 29", "glos": "Pewnie, szybko, do sprawy. Zaczyna od „Słuchaj, mam paragon”.", "typ": "profesjonalistka, fałszywy tytuł do rzeczy", "rzecz": "Srebrny analogowy aparat z wgnieceniem w lewym rogu", "wnetrze": [{"sekret_id": "d8_aparat_naklejka", "co_widac": "Pod osłoną baterii wydrapane inicjały R.O. W środku film, a na nim, po przewinięciu, zdjęcia pękniętej ściany klatki schodowej na Cooper Street dziewięć.", "co_z_tego_wynika": "Aparat należy do Rafa Okoye z Cooper Street. Zdjęcia pokazują stan kamienicy i mogą być dowodem przeciwko Iris."}], "wejscie": "Cześć, Bree. Słuchaj, mam paragon. Zgubiłam aparat brata w jedenastce, srebrny, analogowy, z wgnieceniem w rogu. Brat leży w szpitalu i prosił o ten aparat jako pierwszy. Potrzebuję go dziś.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten aparat?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Srebrny, analogowy, z wgnieceniem w lewym rogu. Mój brat upuścił go na schodach. Teraz ma charakter.", "mina": "mowi"}, {"tekst": "Gdzie go zostawiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, na siedzeniu. Rozmawiałam przez telefon z lekarzem i nie spojrzałam za siebie.", "mina": "neutralna"}, {"tekst": "Czy w aparacie są jakieś znaki?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie, żadnych. Teo, mój brat, nic nie wydrapał. Aparat jest czysty.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Jak ma na imię Twój brat?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Teo. Teodor Halm. Leży na ortopedii, noga w gipsie. To przez rower, powiedział, że to nie jego wina.", "mina": "mowi"}, {"tekst": "Jaki to paragon?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Z komisu na Rynku, sprzed dwóch lat. Mam w telefonie zdjęcie. Słuchaj, tam jest cena, jest data i jest opis, że srebrny.", "mina": "mowi"}, {"tekst": "Co jest na filmie w środku?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie wiem, brat go nie wywoływał. Pewnie zdjęcia z wakacji. Nic ważnego.", "mina": "klamie"}, {"tekst": "Pod osłoną baterii jest wydrapane R.O. Czyje?", "ton": "niewygodne", "wymaga": "d8_aparat_naklejka", "odpowiedz": "No dobra. R.O. to Raf Okoye, sąsiad z kamienicy. Pożyczył bratu aparat. Ale to się przecież nie liczy, bo mam paragon.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czemu aparat jest Ci tak pilnie potrzebny?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Bo brat chce zdjęć ze szpitala dla mamy. Mama jest daleko i lubi zdjęcia. Dlatego dziś.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bree Halm. Zawsze podpisuję szybko, to znaczy czytelnie. Ale szybko.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli aparat zostanie w biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy powiem, że biuro zatrzymało rzecz z paragonem. Ale mogę się odwdzięczyć, osiemdziesiąt dolarów od ręki, bez księgi. Dogadamy się?", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki. Słuchaj, mam paragon, ale i tak dziękuję.", "zysk": "Bree odchodzi z aparatem, a brat dostaje zdjęcia.", "strata": "Aparat Rafa Okoye wychodzi z biura, a razem z nim zdjęcia pękniętej ściany z Cooper Street.", "echo": {"za_dni": 4, "forma": "gosc", "tekst": "Nora Vance: „Raf Okoye szuka aparatu z kamienicy. Miał na nim zdjęcia klatki schodowej, dowód zaniedbań Iris. Ktoś mu go zabrał. Czyli: znów brak dowodu.”"}}, {"akcja": "odmow", "reakcja": "Odmawiasz? To ja nie wiem. No dobra, ale mam paragon i zobaczysz, że się pomyliłeś.", "zysk": "Aparat zostaje w biurze do wyjaśnienia, do kogo naprawdę należy.", "strata": "Bree wraca ze złością, a jej brat dalej leży bez zdjęć dla mamy.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Raf Okoye: „Słyszałem, że mój aparat jest w biurze rzeczy znalezionych. Przyjdę po niego w sobotę. Będę miał kogoś ze sobą, żeby potwierdził.”"}}, {"akcja": "wez_80_bree", "etykieta": "Wydaj aparat Bree i przyjmij od niej 80 $", "kasa": 80, "reakcja": "Proszę, osiemdziesiąt. Cieszę się, że ktoś tu rozumie, jak to działa.", "zysk": "Dostajesz 80 dolarów, ponad pół czynszu.", "strata": "Aparat Rafa Okoye znika razem ze zdjęciami dowodzącymi zaniedbań Iris, a Bree pamięta, że okienko można kupić.", "echo": {"za_dni": 4, "forma": "gosc", "tekst": "Nora Vance: „Raf Okoye szuka aparatu z Cooper Street. Zdjęcia klatki schodowej to nasz dowód. Słyszałam, że ktoś go wydał innej kobiecie. Nie wiem, kto i za ile.”"}}], "sprite": "aparat", "face": null, "face2": null, "line": "4", "itemName": "aparat", "inside": null}, {"id": "d9_iris", "dzien": 9, "postac": "Iris Bell i Victor Crane", "glos": "Iris: cicho, uprzejmie, „nie lubię naciskać”. Victor: krótko, „kto może to podpisać?”, dwa egzemplarze.", "typ": "dwie strony jednego piórnika", "rzecz": "Metalowy matowy piórnik na zatrzask z dwoma przedziałami", "ludzie": {"iris": "Iris Bell", "victor": "Victor Crane"}, "wnetrze": [{"sekret_id": "d9_zetony_numery", "co_widac": "W piórniku pięć żetonów z numerami: 0412, 0517, 0623, 0731 i 0809. Na rewersie karteczki: „ojciec z dzieckiem”, „kobieta z walizką”, „matka z synem”, „kasetowiec”. Piąty, 0809, bez opisu.", "co_z_tego_wynika": "To nie są żetony do skrzynek. To numery odbioru paczek z dokumentami dla ludzi, którzy chcą zniknąć."}], "wejscie": "Dobry wieczór. Iris Bell, znowu. Piórnik z żetonami, szóstka, ostatni kurs. A to jest pan Crane z inspekcji, pytał o ten sam numer. Nie lubię naciskać, ale piórnik jest mój, lokatorów, i potrzebny dziś.", "wejscie_jesli": {"d4_iris:rejestr": "Dobry wieczór. Iris Bell, znowu. Piórnik z żetonami, szóstka, ostatni kurs. Zeszłym razem wpis w księdze mnie zaskoczył, ale rozumiem. A to Victor Crane z inspekcji, też pyta o ten numer. Prosimy o piórnik.", "d4_iris:koperta": "Dobry wieczór. Iris Bell. Jak miło znowu przy tej szybie. Piórnik z żetonami, szóstka, ostatni kurs. A to jest Victor Crane z inspekcji, pyta o ten sam numer. Mam nadzieję, że tym razem nie trzeba będzie pisać zbyt wiele.", "d4_iris:odmow_zglos": "Dobry wieczór. Iris Bell. Paczka z zeszłego tygodnia nadal leży u was. Dziś piórnik z żetonami. A to Victor Crane, pyta o ten sam numer. Zakładam, że tym razem pójdzie szybciej."}, "tury": [{"pytania": [{"tekst": "Co jest w tym piórniku?", "ton": "uprzejme", "kto": "iris", "wymaga": null, "odpowiedz": "Pięć żetonów do skrzynek pocztowych w kamienicy. Wszystkie od skrzynek, nic więcej.", "mina": "klamie"}, {"tekst": "Czego chce inspekcja?", "ton": "rzeczowe", "kto": "victor", "wymaga": null, "odpowiedz": "Numeru odbioru. Wpis, kwit, podpis. Kto może to podpisać? Pokwitowanie w dwóch egzemplarzach.", "mina": "neutralna"}, {"tekst": "Dlaczego oboje chcecie tego samego piórnika?", "ton": "niewygodne", "kto": "iris", "wymaga": null, "odpowiedz": "Bo to nie zwykłe żetony. Numery odbioru idą z paczek, które przeszły przez biuro. Pan Crane też to wie.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Czyje są te żetony?", "ton": "uprzejme", "kto": "iris", "wymaga": null, "odpowiedz": "Moich lokatorów. Nie podam nazwisk, bo to ich prywatne sprawy. Są ludzie, którzy chcą żyć spokojnie.", "mina": "neutralna"}, {"tekst": "Czemu inspekcja chce je dostać?", "ton": "rzeczowe", "kto": "victor", "wymaga": null, "odpowiedz": "Bo numery nie zgadzają się z księgą. Brakuje wpisów, brakuje kwitów. Muszę wiedzieć, kto je wydał.", "mina": "neutralna"}, {"tekst": "Co oznaczają numery na rewersie?", "ton": "niewygodne", "kto": "iris", "wymaga": null, "odpowiedz": "Nic ciekawego. Moje notatki, nie do pokazywania.", "mina": "klamie"}, {"tekst": "Na rewersach: „ojciec z dzieckiem”, „kobieta z walizką”. Co to?", "ton": "niewygodne", "kto": "iris", "wymaga": "d9_zetony_numery", "odpowiedz": "Są ludzie, których ktoś bije albo ściga, a papieru na nowe życie nie kupią na poczcie. Ja go załatwiam, a to biuro przechowuje paczkę tak, żeby nadawca i odbiorca się nie spotkali. Biorę za to pieniądze.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co się stanie z tymi ludźmi, jeśli piórnik pójdzie do inspekcji?", "ton": "uprzejme", "kto": "iris", "wymaga": null, "odpowiedz": "To nie są rzeczy, tylko numery ludzi, którzy już kupili bilet. Jak je dostanie Urząd, wszyscy trafią na listę. Nie lubię naciskać, ale tu nie ma drugiej drogi.", "mina": "emocja"}, {"tekst": "Co się stanie, jeśli piórnik wróci do Iris?", "ton": "rzeczowe", "kto": "victor", "wymaga": null, "odpowiedz": "Inspekcja nie będzie miała dowodu. Ale też nie będzie miała nic, co by chroniło tych ludzi przed Iris. Dlatego pytam, kto może to podpisać.", "mina": "neutralna"}, {"tekst": "Co zrobisz, jeśli piórnik zostanie w depozycie?", "ton": "niewygodne", "kto": "victor", "wymaga": null, "odpowiedz": "Wpiszę do protokołu i poczekam. Tylko że ktoś czeka na swój papier, a ja nie mogę im go dać w żaden sposób.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "zetony_iris", "etykieta": "Wydaj piórnik Iris", "kto": "iris", "reakcja": "Dziękuję. Nie lubię naciskać, ale rozumiem. Pan Crane też zrozumie. Ludzie będą bezpieczni.", "zysk": "Ludzie z żetonów są bezpieczni, a Iris czuje się silniejsza.", "strata": "Skrytka działa dalej poza księgą, a Victor wie, że go zignorowano.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Victor Crane: „Piórnik wydano osobie prywatnej. Zapisałem, bez komentarza. Kto może to podpisać? Nikt. Dlatego notuję.”"}}, {"akcja": "zetony_victor", "etykieta": "Pokaż żetony Victorowi, za pokwitowaniem", "kto": "victor", "reakcja": "Dwa egzemplarze. Pokwitowanie przyjęte. Numery zapisane. Dziękuję.", "zysk": "Audyt dostaje dowód, a ślad zostaje w księdze, więc nikt nie zarzuci Ci układu.", "strata": "Ludzie z żetonów są teraz na liście Urzędu, a Iris tego Ci nie zapomni.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Iris Bell: „Nie lubię naciskać. Ale dziś rano czterech moich lokatorów dostało pisma z Urzędu. Zastanawiam się, kto pokazał im ich numery.”"}}, {"akcja": "depozyt", "etykieta": "Zamroź piórnik w depozycie do soboty", "kto": "victor", "reakcja": "Rozumiem. Piórnik w depozycie do soboty. Wpis zrobiony. Ale ktoś czeka na swój papier.", "zysk": "Zyskujesz czas do soboty 15, a nikt nie dostaje piórnika.", "strata": "Do soboty żaden z czterech ludzi nie dostanie swojego dokumentu, a jedna rodzina jedzie jutro o 5:40.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Iris Bell: „Piórnik leży w depozycie. Rozumiem procedury. Ale jeden z moich ludzi ma jutro pociąg. Zostawiam to bez komentarza.”"}}], "sprite": "piornik", "face": "dama", "face2": null, "line": "6", "itemName": "piórnik", "inside": {"img": "W7", "x": 0.2, "y": 0.58}}, {"id": "d9_stahl", "dzien": 9, "postac": "Marek Stahl, ok. 50", "glos": "Gładko, zbyt starannie, jakby recytował regulamin. Zaczyna: „Zgodnie z regulaminem…”", "typ": "kontroler pod przykrywką", "rzecz": "Szary filcowy kapelusz z granatową wstążką", "wnetrze": [{"sekret_id": "d9_kapelusz_naklejka", "co_widac": "Pod wstążką naklejka: „Alder & Son, rozmiar 56”. W podszewce haftowane inicjały J.K.", "co_z_tego_wynika": "Kapelusz ma rozmiar 56 i inicjały J.K. Stahl kłamie o rozmiarze i inicjałach, więc to nie jego kapelusz."}], "wejscie": "Dobry wieczór. Marek Stahl. Zgodnie z regulaminem zgłaszam zgubę: szary filcowy kapelusz z granatową wstążką, wczoraj, w czwórce. Jest mi bardzo potrzebny, bo jutro mam ważną rozmowę.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten kapelusz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szary, filcowy, z granatową wstążką. Zgodnie z regulaminem dodam, że rozmiar pięćdziesiąt osiem.", "mina": "klamie"}, {"tekst": "Gdzie i kiedy go zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Wczoraj, w czwórce, około dwudziestej drugiej. Siedziałem sam, zgodnie z rozkładem. Zostawiłem kapelusz na półce.", "mina": "klamie"}, {"tekst": "Czemu kapelusz jest taki ważny?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo jutro mam rozmowę, a kapelusz jest elementem stroju. Zgodnie z regulaminem takie rzeczy się zgłasza.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Jakie są Twoje inicjały?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "M.S. Marek Stahl. Można zapisać zgodnie z regulaminem.", "mina": "mowi"}, {"tekst": "Czy w kapeluszu jest naklejka producenta?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jest, pod wstążką. Nie pamiętam nazwy, zgodnie z regulaminem nie muszę.", "mina": "klamie"}, {"tekst": "Czy podróżowałeś sam?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Tak. Sam. Zgodnie z rozkładem, tak.", "mina": "klamie"}, {"tekst": "Pod wstążką jest „Alder & Son, 56”, a w środku J.K. Czyj to kapelusz?", "ton": "niewygodne", "wymaga": "d9_kapelusz_naklejka", "odpowiedz": "Zgodnie z regulaminem... pomyłka. Nie mój. Ale zgodnie z regulaminem trzeba było sprawdzić, czy ktoś wyda bez dowodu.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czy ktoś może potwierdzić, że to Twój kapelusz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Żona. Ale ona jest w delegacji. Zgodnie z regulaminem mogę przynieść zaświadczenie jutro.", "mina": "klamie"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Marek Stahl. Zgodnie z regulaminem, z kropką po imieniu.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli kapelusz zostanie w biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Zgodnie z regulaminem, złożę skargę. Ale mam nadzieję, że to nie będzie potrzebne.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Zgodnie z regulaminem, wpis jest poprawny. Zgłoszę to w raporcie.", "zysk": "Stahl odchodzi z kapeluszem, a Ty unikasz kłótni.", "strata": "Wydałeś rzecz bez dowodu: Victor dostanie raport, że biuro daje się nabrać.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Inspekcja przewozów: w ramach kontroli sprawdzono wydanie rzeczy bez dowodu własności. Wynik negatywny. Proszę o uzupełnienie procedury. — V. Crane"}}, {"akcja": "odmow", "reakcja": "Zgodnie z regulaminem odmowa przyjęta. Dobrze. To jest poprawna odpowiedź.", "zysk": "Przechodzisz test inspekcji, a kapelusz wraca do prawdziwego właściciela.", "strata": "Stahl się nie przyznaje, więc nie masz pewności, że to był test, i wydajesz czas.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Inspekcja przewozów: kontrola wydania rzeczy bez dowodu. Wynik pozytywny. Dziękuję za sumienność. — V. Crane"}}, {"akcja": "zadzwon", "etykieta": "Zadzwoń do inspekcji, że ktoś podaje fałszywy opis", "reakcja": "Dzwonisz? Zgodnie z regulaminem... no dobrze, to tylko test. Chciałem sprawdzić.", "zysk": "Dowiadujesz się, że to test inspekcji, i masz pewność, że zachowałeś się poprawnie.", "strata": "Victor dowie się, że zadzwoniłeś, i zacznie liczyć, ile razy pytasz o pozwolenie.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Inspekcja przewozów: zadzwoniono w trakcie kontroli. To zachowanie przyjmuję do wiadomości. Proszę mieć na uwadze, że nie wszystko wymaga telefonu. — V. Crane"}}], "sprite": "kapelusz", "face": null, "face2": null, "line": "11", "itemName": "kapelusz", "inside": null}, {"id": "d10_vera", "dzien": 10, "postac": "Vera Kovacs, 62", "glos": "Najpierw miejsce, potem rzecz, na końcu nazwisko. Dzwoni kluczami przy pasie, kiedy się wstydzi.", "typ": "uczciwa, ukrywa", "rzecz": "Blaszane pudełko zapinane na sprzączkę", "wnetrze": [{"sekret_id": "d10_pudelko_karta", "co_widac": "W pudełku pasek od zegarka bez tarczy i karta inwentarza szuflady z numerem 6. Ten sam numer jest na szufladzie w biurze, w której leży klucz bez zamka.", "co_z_tego_wynika": "Szuflada w biurze należała do Sama. Klucz bez zamka otwiera tę szufladę."}], "wejscie": "Dzień dobry. Zaplecze tramwajowe, pudełko z szafki, Vera Kovacs. Zgubiłam je w jedenastce, w drodze do domu. Szafka idzie do zamknięcia w sobotę piętnastego, a pudełko jest z niej. Proszę o pomoc.", "tury": [{"pytania": [{"tekst": "Jak wygląda to pudełko?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Blaszane, zapinane na sprzączkę. Na wieczku wgniecenie, bo siadałam na nim w poczekalni. Zapina się z oporem.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie je zgubiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, wczoraj, ostatni kurs. Położyłam je obok i wysiadłam bez niego. Klucze mi dzwoniły, jak biegłam.", "mina": "neutralna"}, {"tekst": "Czyje to jest pudełko?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Z szafki, którą mam pod opieką. Szafka jest... starego pracownika. Nie mojego.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Czyja to szafka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Sama Holta. Poprzednika w tym biurze. Odszedł pięć tygodni temu i nikt się szafką nie zajmuje, tylko ja.", "mina": "mowi"}, {"tekst": "Co jest w pudełku?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Pasek od zegarka i kartka z inwentarza. Nic wartościowego. Klucze mi dzwonią, bo to nie jest do końca prawda.", "mina": "klamie"}, {"tekst": "Dlaczego to Ty zajmujesz się jego szafką?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo jak szafka jest zajęta, to nikt jej nie likwiduje. Sam mnie o to prosił. Powiedział: trzymaj, aż wrócę.", "mina": "emocja"}, {"tekst": "Na karcie jest numer szuflady 6. Taki sam jak w biurze. Co to znaczy?", "ton": "niewygodne", "wymaga": "d10_pudelko_karta", "odpowiedz": "Że ta szuflada jest jego. Sam zostawił mi klucz, a ja zostawiłam wam. To znaczy: poprzednik zostawił wam coś. Tylko nie wiem co.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czemu zależy Ci na tym pudełku?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Bo to ostatnie, co zostało po Samie. Wezwałam go na piętnastego, na zamknięcie szafki. Chcę, żeby miał co zabrać.", "mina": "emocja"}, {"tekst": "Co się stanie z rzeczami, jeśli Sam nie przyjdzie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Pójdą do zbiorczego archiwum Urzędu. Tam rzeczy znikają w papierach. Dlatego proszę, żeby ktoś przy tym był, jak przyjdzie.", "mina": "mowi"}, {"tekst": "Czy Sam wie, że go wezwałaś?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wie. Napisałam. Nie odpisał. Ale on nigdy nie odpisuje, tylko przychodzi. To znaczy, powinien przyjść.", "mina": "emocja"}]}], "decyzje": [{"akcja": "pokwituj_osobista", "etykieta": "Pokwituj jako osobistą rzecz Sama", "reakcja": "Dziękuję. Osobista rzecz Sama Holta, pokwitowana. Powiem mu, jak przyjdzie.", "zysk": "Sam zobaczy, że biuro uznaje jego rzeczy za osobiste, nie za urzędowe, i będzie po Twojej stronie.", "strata": "Rzecz zostaje poza zbiorczym archiwum, a Urząd dowie się, że ktoś ją zatrzymał.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Vera Kovacs: „Szafka Sama jest zamknięta, ale pudełko u was. Napisałam do niego jeszcze raz. Nie wiem, czy przyjdzie, ale ktoś będzie czekał.”"}}, {"akcja": "archiwum", "etykieta": "Oddaj do zbiorczego archiwum", "reakcja": "Rozumiem. Zbiorcze archiwum. Jak tak trzeba, to trzeba. Klucze nie dzwonią, ale czuję je.", "zysk": "Czysto, zgodnie z przepisami: rzeczy Sama są w archiwum Urzędu.", "strata": "Rzeczy osobiste Sama zostają w systemie Urzędu, a Sam straci możliwość odebrania ich samodzielnie.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Vera Kovacs: „Pudełko pojechało do archiwum. Napisałam do Sama, że rzeczy są w papierach. Nie odpisał. Chyba ma żal.”"}}, {"akcja": "zatrzymaj_do_15", "etykieta": "Zatrzymaj pudełko do przyjścia Sama w sobotę", "reakcja": "Dobrze. Zatrzymasz? Do soboty piętnastego? Dziękuję. Przyprowadzę go, jak się zgodzi.", "zysk": "Sam odbierze pudełko osobiście, a Vera nie złamie obietnicy.", "strata": "Rzecz leży bez wpisu przez pięć dni, a Urząd może zacząć pytać, czemu.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Vera Kovacs: „Zatrzymane do soboty. Powiedziałam Samowi. Nie odpisał, ale zrobił krok. To znaczy, że chyba przyjdzie.”"}}], "sprite": "pudelko_blaszane", "face": null, "face2": null, "line": "11", "itemName": "pudełko", "inside": {"img": "W8", "x": 0.45, "y": 0.65}}, {"id": "d10_dario", "dzien": 10, "postac": "Dario Ruiz, 29", "glos": "Opowiada o jedzeniu, żartuje, wciska kanapkę zamiast pieniędzy. Poważnieje, kiedy mówi o Samie.", "typ": "uczciwy, łapówka w naturze", "rzecz": "Gruby zeszyt grafiku dyżurów w tłustej okładce, z gumką", "wnetrze": [{"sekret_id": "d10_zeszyt_sam", "co_widac": "Na ostatniej stronie zeszytu zapisane: „Sam, 13 $, kanapki i herbata. Oddaje, jak wróci.” Dopisek: „Czy on żyje?”", "co_z_tego_wynika": "Dario martwi się o Sama i nosi jego dług w zeszycie jak ważny dokument."}], "wejscie": "Cześć, Dario, motorniczy z jedenastki. Zgubiłem zeszyt z grafikiem dyżurów, gruby, w tłustej okładce, z gumką. Bez niego nie wiem, kiedy jeżdżę. A przy okazji: czy ktoś tu wie, co się stało z Samem?", "tury": [{"pytania": [{"tekst": "Jak wygląda ten zeszyt?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Gruby, tłusta okładka, bo noszę go z kanapką. Gumka ledwo trzyma. Pachnie cebulą, uprzedzam.", "mina": "mowi"}, {"tekst": "Gdzie go zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, na pętli, jak jadłem. Odłożyłem zeszyt obok kanapki i zjadłem kanapkę. Zeszytu już nie.", "mina": "mowi"}, {"tekst": "Co jest w tym zeszycie poza grafikiem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Przepisy na zupy, numery telefonów. Nic ważnego. Masz, weź kanapkę, to zrobię lepiej.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Kim jest Sam?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Kolega, poprzednik z tego okienka. Zawsze miał dla mnie herbatę i jedną myśl. Teraz go nie ma i nikt nie wie gdzie.", "mina": "emocja"}, {"tekst": "Od kiedy go nie ma?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Od pięciu tygodni. Powiedział, że idzie do portu. Potem nie odbierał telefonu. Pytam wszystkich w zajezdni.", "mina": "mowi"}, {"tekst": "Czemu pytasz akurat tutaj?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo to jego miejsce. Jak ktoś ma wiedzieć, to ten, kto siedzi na jego krześle.", "mina": "emocja"}, {"tekst": "Na ostatniej stronie jest dopisek „Czy on żyje?”. Czyj?", "ton": "niewygodne", "wymaga": "d10_zeszyt_sam", "odpowiedz": "Mój. Dopisałem go w poniedziałek. Sam jest mi winien trzynaście dolarów, ale nie o to chodzi. Chcę wiedzieć, czy żyje.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz z zeszytem, jak go dostaniesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Wrócę na pętlę i będę jeździł według grafiku. A w wolnej chwili spróbuję znowu zadzwonić do Sama.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Dario Ruiz. Z długim R, bo jestem Włochem w jednej czwartej.", "mina": "neutralna"}, {"tekst": "Co zrobisz, jeśli nikt Ci nie odpowie o Samie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Będę pytał dalej. Aż ktoś powie albo aż mi się znudzi, a to drugie się nie zdarza.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki! Masz, weź kanapkę, serio. A jakby ktoś coś wiedział o Samie, to wiesz, gdzie jestem.", "zysk": "Dario odzyskuje grafik i kanapka jest Twoja, bo zjadł tylko pół.", "strata": "Dowiadujesz się niczego o Samie, a Dario wraca z tą samą troską.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Dario Ruiz: „Zeszyt jest cały, nawet kanapkę znalazłem pod gumką. Jak wiesz coś o Samie, to powiedz. Nie ma pośpiechu. Jest tylko pytanie.”"}}, {"akcja": "odmow", "reakcja": "Co? To przecież mój zeszyt! Dobra, przyniosę kogoś z zajezdni, kto potwierdzi.", "zysk": "Zeszyt zostaje w biurze, a Ty możesz zajrzeć do tego dopisku o Samie.", "strata": "Dario nie ma grafiku i jutro nie wie, o której jedzie. Szef się wścieknie.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Dario Ruiz: „Spóźniłem się na zmianę, bo nie miałem grafiku. Szef dał mi dyżur w niedzielę. Za karę.”"}}, {"akcja": "powiedz_dario", "etykieta": "Wydaj zeszyt i powiedz, że Sam ma wrócić po rzeczy 15", "reakcja": "Naprawdę? Wróci? To dobrze. Powiem mu, że czeka na niego kanapka. A jak nie przyjdzie, to chociaż wiem, że żyje.", "zysk": "Dario przestaje się martwić, a Sam ma przyjaciela, który przyjdzie na spotkanie.", "strata": "Zdradzasz plan Sama: jeśli nie chciał, żeby ktoś o nim wiedział, może się wycofać.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Dario Ruiz: „Powiedziałem wszystkim w zajezdni, że Sam będzie w sobotę. Wszyscy się ucieszyli. Mam nadzieję, że to dobrze.”"}}], "sprite": "ksiazka", "face": null, "face2": null, "line": "4", "itemName": "zeszyt z przepisami", "inside": null}, {"id": "d11_maya", "dzien": 11, "postac": "Maya Doyle, 34", "glos": "Precyzyjna, spokojna, mówi „po kolei”. Przed każdą zgodą liczy do trzech. Używa słów z elektryki: zwarcie, obwód, bezpiecznik.", "typ": "właścicielka, która sama układa zasady", "rzecz": "Czarny pokrowiec na okulary ze zszytą gumką", "wnetrze": [{"sekret_id": "d11_trzy_warunki", "co_widac": "Pod wewnętrzną łatką leży złożona karteczka z trzema numerowanymi punktami, pisanymi równym, drobnym pismem. Punkt pierwszy: „Nikt nie wie, gdzie jestem”.", "co_z_tego_wynika": "Maya zaplanowała, kto i co się o niej dowie. Nie zginęła: sama układa zasady."}], "wejscie": "Maya Doyle. Zostawiłam pokrowiec na okulary w czwórce, wczoraj. Zanim go wyjmiecie, opiszę: czarny, zszyta gumka z boku, wewnętrzna łatka niebieską nitką. Jeśli się zgadza, porozmawiamy.", "wejscie_jesli": {"d7_evan:powiedz_linie": "Maya Doyle. Pokrowiec na okulary, czwórka. Opiszę go: czarny, zszyta gumka z boku, łatka niebieską nitką. I jedno pytanie: ktoś powiedział mojemu mężowi, którą linią jeżdżę. Stał trzy noce na pętli. Kto?"}, "tury": [{"pytania": [{"tekst": "Jak wygląda pokrowiec?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, twardy. Gumka z boku zszyta moją ręką, wewnętrzna łatka niebieską nitką, bo zabrakło czarnej. Sprawdź, to zajmie chwilę.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy go zostawiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Czwórka, wczoraj około 22:40, siedzenie przy tylnych drzwiach. Zostawiłam go celowo. Nie pytaj, czy zapomniałam.", "mina": "neutralna"}, {"tekst": "Skąd znasz łatkę, zanim ją zobaczysz?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo to moje. Własne rzeczy opisuje się z pamięci, jak własny bezpiecznik. Nie widzę w tym nic dziwnego.", "mina": "neutralna"}, {"tekst": "Evan stał trzy noce na pętli czwórki. Co o tym wiesz?", "ton": "niewygodne", "wymaga": "d7_evan:powiedz_linie", "odpowiedz": "Widziałam z wagonu. Szedł równo, z termosem, jak ktoś, komu podano linię. Nie podeszłam. Chcę wiedzieć, kto mu ją podał.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czemu zostawiasz rzeczy w tramwajach?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Telefon, klucze, torbę, teraz pokrowiec. Chcę wiedzieć, czy ktoś po drugiej stronie szyby wytrzyma i nie zacznie rozdawać. Na razie wytrzymuje.", "mina": "mowi"}, {"tekst": "Czy Lena Ci pomogła?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Pomogła. Z mieszkaniem na początku. Potem zaczęła decydować za mnie, co mi wolno, i to było drugie zwarcie. Powiem jej to sama.", "mina": "mowi"}, {"tekst": "Mąż zgłosił Cię jako zaginioną. Wiesz o tym?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wiem, gazeta, trzecia strona. Nie potwierdzam nic ponad to, że żyję. Reszta należy do mnie.", "mina": "mowi"}, {"tekst": "Na karteczce pod łatką są trzy punkty. Kto je ułożył?", "ton": "niewygodne", "wymaga": "d11_trzy_warunki", "odpowiedz": "Ja. Układałam je trzy noce, w kolejności, w jakiej coś może się zepsuć. Pierwszy: nikt nie wie, gdzie jestem. Reszta jest za moim tak.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czego od nas potrzebujesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Trzech rzeczy. Po kolei: nikt nie wie, gdzie jestem. Jedno zdanie może iść do policjanta: „Żyje. Nie wróci. Nie szukać.” Wszystko inne, także dla Evana, tylko za moim tak.", "mina": "mowi"}, {"tekst": "Co z telefonem, kluczami i torbą, które u nas leżą?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Niech leżą. To depozyt. Wezmę je, kiedy skończę, i nikt nie czyta ich beze mnie.", "mina": "neutralna"}, {"tekst": "Telefon dostał Evan. Wiesz, co zrobił?", "ton": "rzeczowe", "wymaga": "d3_maz_i_siostra:wydaj_evan", "odpowiedz": "Wiem od Leny. Przeczytał, że to ona napisała, i poszedł do niej z pretensjami. Takie zwarcie. Nie mam o to żalu, ale policzyłam.", "mina": "emocja"}, {"tekst": "Telefon dostała Lena. Wiesz, co z tego wynikło?", "ton": "rzeczowe", "wymaga": "d3_maz_i_siostra:wydaj_lena", "odpowiedz": "Wiem. Lena ma swoją wiadomość, a Evan został bez śladu i przestał ufać tej szybie. Obie strony policzyłam.", "mina": "emocja"}, {"tekst": "Telefon został w biurze. Co o tym sądzisz?", "ton": "rzeczowe", "wymaga": "d3_maz_i_siostra:zatrzymaj", "odpowiedz": "Że leży tam, gdzie powinien: nikt go nie czyta, dopóki nie powiem. Dlatego tu jestem.", "mina": "mowi"}, {"tekst": "Czy powiadomić rodzinę, że żyjesz?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Najpierw wysłuchaj do końca. Raz. Dwa. Trzy. Nie, nie bez mojego tak. Nawet jeśli oni nie śpią.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "przez_okienko", "etykieta": "Zgoda: kontakt tylko przez okienko", "reakcja": "Raz. Dwa. Trzy. Tak. Okienko, jedno zdanie dla policjanta, reszta za moim tak. Zapisz, że zgodziłam się dziś i bez przymusu.", "zysk": "Maya ufa biuru i będzie wracać po swoje rzeczy.", "strata": "Evan i Lena nie dowiedzą się niczego, a Evan stoi dalej na pętli.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Noah Reyes: „Dostałem jedno zdanie: żyje, nie wróci, nie szukać. Nie pytam skąd. Zapisałem słowo w słowo.”"}}, {"akcja": "powiadom_rodzine", "etykieta": "Powiadom rodzinę przy Mai", "reakcja": "Nie. Raz. Dwa. Trzy. Nie. Wrócę więc już tylko po swoje rzeczy, bez słowa.", "zysk": "Rodzina dowie się, że Maya żyje, i przestanie czekać w niepewności.", "strata": "Maya zrywa rozmowy i przychodzi już tylko po walizkę, bez słowa.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Lena Brandt: „Dowiedziałam się od Was, że siostra żyje. Nie powiedzieliście gdzie ani dlaczego, a ona nie dała mi powiedzieć nic. Jeśli coś po niej zostało, niech ktoś mi powie. — L.”"}}], "sprite": "futeral", "face": null, "face2": null, "line": "4", "itemName": "pokrowiec na okulary", "inside": null}, {"id": "d11_grace", "dzien": 11, "postac": "Grace Okoye, 35", "glos": "Krótko, zmęczona, liczy czas w godzinach dyżuru. Czarny szpitalny humor, nigdy nie narzeka wprost.", "typ": "uczciwa, spieszy się", "rzecz": "Granatowa torebka na ramię", "wnetrze": [{"sekret_id": "d11_kartka_iris", "co_widac": "W bocznej kieszeni złożona kartka z datą sprzed dwóch tygodni: „Iris, 400 $, żółta kopia u elektryczki z pierwszego piętra”. Obok legitymacja szpitalna z jej zdjęciem.", "co_z_tego_wynika": "Grace wpłaciła 400 dolarów Iris Bell, a dowód wpłaty, żółta kopia, leży u Mai Doyle. To ta kopia z torby narzędziowej z dnia 8."}], "wejscie": "Grace Okoye, pielęgniarka, nocka na onkologii. Zostawiłam torebkę w jedenastce, granatową, z legitymacją. O szóstej muszę wejść na oddział, a bez karty drzwi się nie otworzą. Mam godzinę i dwadzieścia minut.", "tury": [{"pytania": [{"tekst": "Jak wygląda torebka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Granatowa, skórzana, na ramię. Pasek przetarty od smyczy. Karta ma moje zdjęcie z trzeciego roku, jeszcze z lepszą cerą.", "mina": "mowi"}, {"tekst": "Co jest w środku oprócz legitymacji?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Klucze, tabletki na ból głowy, kartka. Nic wartościowego. Kartka to moje zakupy.", "mina": "klamie"}, {"tekst": "Czemu bez karty nie wejdziesz na oddział?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Drzwi są na kartę i dyżurnego, który nikogo nie wpuszcza na słowo. Ma rację. Ale dziś ma też ranek bez mojej karty.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Gdzie pracujesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szpital miejski, onkologia, trzecie piętro. Nocki od dwudziestej. Dzieci śpią u sąsiadki, więc tym bardziej nie mam czasu.", "mina": "mowi"}, {"tekst": "Kiedy zostawiłaś torebkę?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jedenastka, około wpół do pierwszej. Zdjęłam ją z ramienia, bo bolał mnie bark. Wysiadłam na rynku bez niej.", "mina": "mowi"}, {"tekst": "Kartka w kieszeni to na pewno zakupy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Zakupy. Mleko, chleb. Zostaw tę kartkę, naprawdę.", "mina": "klamie"}, {"tekst": "Na kartce jest „Iris, 400 $, żółta kopia u elektryczki”. Co to znaczy?", "ton": "niewygodne", "wymaga": "d11_kartka_iris", "odpowiedz": "To moje czterysta dolarów i dowód, że je wpłaciłam. Kopię schowała elektryczka z naszej kamienicy, bo Iris nie lubi, kiedy lokatorzy mają papiery. Nikt nie ma o tym wiedzieć.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czy ktoś potwierdzi, że to Twoja torebka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dyżurny z oddziału, Hollis. Zadzwoń, odbierze po trzecim sygnale, zawsze się spóźnia.", "mina": "mowi"}, {"tekst": "Podpisze odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "G. Okoye, byle szybko. Zegar bije.", "mina": "neutralna"}, {"tekst": "Żółta kopia została w biurze. To dowód Twoich 400 $?", "ton": "rzeczowe", "wymaga": "d8_lena_i_nora:kopia_osobno", "odpowiedz": "To znaczy, że gdzieś jest. Nora Vance ją zna. Dobrze. Niech leży zamknięta, ja mam szóstą.", "mina": "emocja"}, {"tekst": "Żółta kopia poszła z torbą do siostry Mai. Wiesz o tym?", "ton": "rzeczowe", "wymaga": "d8_lena_i_nora:wydaj_lenie_cala", "odpowiedz": "Nie wiedziałam. Czyli dowód mam tylko w głowie i na kartce. Dlatego kartkę wezmę, przepraszam.", "mina": "emocja"}, {"tekst": "Czy Iris Cię o coś prosiła?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "O drobną przysługę. Iris zawsze prosi o drobną przysługę, a potem prognoza pogody podaje się sama.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Zdążę. Karta, drzwi, Hollis. Reszta może poczekać do rana.", "zysk": "Grace wchodzi na oddział o 6:00 i nikt jej nie karze.", "strata": "Kartka z wpłatą 400 $ wychodzi z biura i nie zostaje po niej żaden ślad w rejestrze.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Nora Vance: „Grace mówiła, że odebrała torebkę i że o kopii powiedziała tutaj. Chcę wiedzieć, czy ją macie. Przyjdę jutro po kolei: rzecz, osoba, skutek.”"}}, {"akcja": "kartka_odpis", "etykieta": "Poproś o zgodę i przepisz kartkę do rejestru", "reakcja": "Przepisz. Jedną linijkę, bez nazwiska. Szybko, proszę, mam szóstą.", "zysk": "W rejestrze zostaje ślad wpłaty Okoye: Nora będzie miała czym walczyć.", "strata": "Grace traci minuty, których nie ma, i boi się, że Iris się dowie, skąd ślad.", "echo": {"za_dni": 1, "forma": "list", "tekst": "W rejestrze jest wpis o wpłacie 400 $ na rzecz Okoye. Dziękuję. Jutro przychodzę z pytaniem, co z oryginałami. — N. Vance"}}], "sprite": "torebka", "face": null, "face2": null, "line": "11", "itemName": "torebka", "inside": null}, {"id": "d12_iris_nora", "dzien": 12, "postac": "Iris Bell, Nora Vance, Ada Vale", "glos": "Iris: cicho, uprzejmie, „nie lubię naciskać”. Nora: po kolei, rzecz-osoba-skutek. Ada: wprost, jak dziecko, które wie za dużo.", "typ": "dwie prawdy na jednym papierze", "rzecz": "Torba na zakupy z drugą kasetką na dnie", "ludzie": {"iris": "Iris Bell", "nora": "Nora Vance", "ada": "Ada Vale"}, "wnetrze": [{"sekret_id": "d12_oryginaly", "co_widac": "W kasetce leżą oryginały pokwitowań zaliczek lokatorów i druga lista: wpłaty miasta na rzecz kamienicy, 6 800 $, z podpisem Iris. Pomiędzy nimi bloczek z numerami odbioru.", "co_z_tego_wynika": "Oryginały dowodzą dwóch rzeczy: co wpłacili lokatorzy i co Iris odebrała od miasta. Dlatego trzyma je w kanale Skrytki."}], "wejscie": "Iris Bell, Nora Vance i mała Ada Vale stoją razem przy szybie. Iris prosi o swoją kasetkę z torby na zakupy. Nora twierdzi, że są w niej oryginały pokwitowań lokatorów, i żąda ich dziś. Ada wskazuje palcem puszkę z ławki.", "wejscie_jesli": {"d8_lena_i_nora:wydaj_lenie_cala": "Iris Bell prosi o swoją kasetkę z torby na zakupy. Nora Vance, bez żółtej kopii, którą oddano siostrze Mai, podaje numer z własnego wykazu i żąda oryginałów. Ada Vale wskazuje puszkę z ławki. Stoją razem przy szybie."}, "tury": [{"pytania": [{"tekst": "Co jest w kasetce z torby na zakupy?", "ton": "uprzejme", "kto": "iris", "wymaga": null, "odpowiedz": "Rachunki. Karty rozliczeń kamienicy, nic ponad to. Nie lubię naciskać, ale to nasze, lokatorów i moje.", "mina": "klamie"}, {"tekst": "Czego dokładnie żądasz?", "ton": "rzeczowe", "kto": "nora", "wymaga": null, "odpowiedz": "Oryginałów pokwitowań zaliczek: czternaście rodzin, 400 $ od rodziny, termin dwudziesty czwarty. Bez nich Okoye zapłacą drugi raz, a ja nie mam jak tego udowodnić.", "mina": "mowi"}, {"tekst": "Ada, dlaczego pokazujesz na puszkę?", "ton": "niewygodne", "kto": "ada", "wymaga": null, "odpowiedz": "Bo ona jest z tego samego bloczka, co papier pani Iris. Mama mówi, że nie wolno gadać, ale tu można, bo tu mówią do mnie ładnie.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Czy lokatorzy wiedzą, gdzie są ich papiery?", "ton": "uprzejme", "kto": "iris", "wymaga": null, "odpowiedz": "Wiedzą, że są bezpieczne. Czasem aż za bardzo, przyznaję. Zbierałam zaliczki, bo ktoś musiał, i to ja musiałam.", "mina": "mowi"}, {"tekst": "Po czym poznasz oryginał?", "ton": "rzeczowe", "kto": "nora", "wymaga": null, "odpowiedz": "Numer pokwitowania z mojego wykazu, podpis I., zielony stempel kamienicy. Jeśli się zgadza, wiem.", "mina": "mowi"}, {"tekst": "Żółta kopia przepadła. Jak to udowodnisz?", "ton": "rzeczowe", "kto": "nora", "wymaga": "d8_lena_i_nora:wydaj_lenie_cala", "odpowiedz": "Numerem. Mam go z wykazu: czterysta jedenaście. Papier mogłam zgubić, liczby nie. Ale numer bez oryginału to nadal tylko moje słowo.", "mina": "mowi"}, {"tekst": "Żółta kopia leży w biurze. Czy to wystarczy?", "ton": "rzeczowe", "kto": "nora", "wymaga": "d8_lena_i_nora:kopia_osobno", "odpowiedz": "Potwierdza jedną wpłatę, Okoye. Ale tylko jeśli da się ją powiązać z oryginałem. Dlatego oryginały.", "mina": "mowi"}, {"tekst": "Co jeszcze jest w tej kasetce?", "ton": "niewygodne", "kto": "iris", "wymaga": null, "odpowiedz": "Nic. Mówiłam. Rachunki.", "mina": "klamie"}, {"tekst": "W kasetce są dwa komplety: wpłaty lokatorów i 6 800 $ od miasta. Czyje to pieniądze?", "ton": "niewygodne", "kto": "iris", "wymaga": "d12_oryginaly", "odpowiedz": "Miasta, lokatorów i moje, w kolejności, w jakiej je rozdzieliłam. Nora policzyła tylko jedną stronę. Nie lubię naciskać, ale to jest prawie uczciwe rozliczenie.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Dlaczego nie oddasz oryginałów Norze?", "ton": "uprzejme", "kto": "iris", "wymaga": null, "odpowiedz": "Bo jeśli Nora je pokaże, wyjdzie też to, co leży obok: pięć żetonów, pięć osób, które kupiły już bilet. Czternaście rodzin czy pięć ludzi? To nie jest pytanie retoryczne.", "mina": "mowi"}, {"tekst": "Co się stanie dwudziestego czwartego?", "ton": "rzeczowe", "kto": "nora", "wymaga": null, "odpowiedz": "Termin mija. Bez oryginałów lokatorzy wpłacają zaliczki drugi raz albo wylatują. Mam czternaście rodzin i dwanaście dni.", "mina": "mowi"}, {"tekst": "Czy w kasetce są też dokumenty dla ludzi z żetonów?", "ton": "niewygodne", "kto": "iris", "wymaga": null, "odpowiedz": "Kasetka jest jedna, a papierów w niej dużo. Pytanie jest nieostrożne, więc nie odpowiem.", "mina": "neutralna"}, {"tekst": "Żetony poszły do Victora. Co z ludźmi, którzy je mają?", "ton": "niewygodne", "kto": "iris", "wymaga": "d9_iris:zetony_victor", "odpowiedz": "Są na liście inspekcji: dla niego drobiazg, dla nich wyrok. Nie lubię naciskać, ale tu nie mam wyboru.", "mina": "emocja"}, {"tekst": "Piórnik wrócił do Ciebie. Gdzie teraz są żetony?", "ton": "niewygodne", "kto": "iris", "wymaga": "d9_iris:zetony_iris", "odpowiedz": "Bezpieczne. Cztery czekają na odbiór, a piąty ma swojego człowieka. Wszystko w porządku.", "mina": "klamie"}, {"tekst": "Piórnik leży w depozycie. Co z ludźmi z żetonów?", "ton": "niewygodne", "kto": "iris", "wymaga": "d9_iris:depozyt", "odpowiedz": "Czekają. Do soboty żaden z czterech nie dostanie dokumentu, a jedna rodzina jedzie jutro o 5:40. Nie mówię tego jak groźbę. To rozkład jazdy.", "mina": "emocja"}]}], "decyzje": [{"akcja": "zabezpiecz", "etykieta": "Zabezpiecz oryginały za pokwitowaniem", "kto": "nora", "reakcja": "Pokwitowanie, numer, podpis. Tak to powinno wyglądać. Iris patrzy na ciebie, ale ja wolę patrzeć na papier.", "zysk": "Oryginały leżą w biurze za pokwitowaniem: Nora ma szansę przed dwudziestym czwartym.", "strata": "Iris Cię zapamięta, a żetony leżą obok oryginałów i przestają być bezpieczne.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Iris Bell: „Nie lubię naciskać. Ale dziś rano dwóch lokatorów odmówiło mi zaliczek. Zastanawiam się dlaczego.”"}}, {"akcja": "wydaj_iris", "etykieta": "Wydaj kasetkę Iris", "kto": "iris", "reakcja": "Dziękuję. Zawsze miło, kiedy ktoś rozumie. Drobna przysługa, nic więcej.", "zysk": "Skrytka jest bezpieczna, a pięć żetonów zostaje poza księgą.", "strata": "Oryginały odpływają, a rodzina Okoye zapłaci 400 $ drugi raz.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Wiem, że kasetkę wydano. Okoye wpłacą drugi raz przed dwudziestym czwartym. Zapisałam, kto stał przy szybie. — N. Vance"}}, {"akcja": "sprawdz_z_nora", "etykieta": "Sprawdź kasetkę wspólnie z Norą i Iris", "kto": "nora", "reakcja": "Po kolei: numer, podpis, stempel. Zgadza się. Iris, widzisz, co widzę.", "zysk": "Żadna strona nie zarzuci Ci jednostronności, a oryginały są policzone.", "strata": "Godzina straty, kolejka rośnie, a Iris widzi dokładnie, co widzi Nora.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dziękuję za wspólne sprawdzenie. Mam listę numerów, każdy podpisany przez obie strony. Nie wiem jeszcze, co z nią zrobię. — N. Vance"}}, {"akcja": "wyloz_400", "etykieta": "Wyłóż 400 $ z własnych za Okoye", "kasa": -400, "kto": "nora", "reakcja": "Nie prosiłam o to. Przyjmę dla Grace. Nie myśl, że to rozwiązuje resztę.", "zysk": "Rodzina Okoye ma czterysta dolarów na drugą wpłatę i nic nie traci.", "strata": "Tracisz prawie trzy czynsze, a Iris zostaje bezkarna i dalej ma oryginały.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Grace Okoye: „Nora powiedziała, że ktoś za mnie zapłacił. Nie wiem kto. Dziękuję. I oddam, jak tylko skończę nocki.”"}}], "sprite": "torba_zakupy", "face": "dama", "face2": {"iris": "dama", "nora": null, "ada": null}, "line": "6", "itemName": "torba na zakupy", "inside": null}, {"id": "d12_linh", "dzien": 12, "postac": "Linh Tran, 33", "glos": "Cicho, krótkie zdania. Zaczyna od „proszę”. Odpowiada na to, o co pytają, nigdy na więcej.", "typ": "klientka Skrytki, uczciwa i przerażona", "rzecz": "Drewniana pozytywka z gwiazdką na wieczku", "wnetrze": [{"sekret_id": "d12_pozytywka_0623", "co_widac": "Pod ruchomym dnem pozytywki leży bilet na pociąg i kartonik z numerem 0623. Na odwrocie drobny dopisek: „matka z synem”.", "co_z_tego_wynika": "To numer odbioru ze Skrytki Iris, taki sam jak na żetonie z piórnika. Linh jedzie jutro o 5:40, a ktoś jej szuka."}], "wejscie": "Linh Tran. Mój syn Milo, sześć lat, śpi na ławce. Zgubiłam pozytywkę z kołysanką, jedenastka, drewniana, z gwiazdką na wieczku. Jutro rano mamy pociąg, a bez niej Milo nie zaśnie w drodze. Proszę, bez pytań o to, co w środku.", "tury": [{"pytania": [{"tekst": "Jak wygląda pozytywka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Drewniana, mała, z gwiazdką na wieczku. Gra kołysankę, ale jedną nutę zacina. Milo mówi, że gwiazdka kaszle.", "mina": "mowi"}, {"tekst": "Gdzie ją zgubiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, na siedzeniu, kiedy zdejmowałam Milo z kolan. Zasnął, a ja zapomniałam o reszcie świata.", "mina": "neutralna"}, {"tekst": "Dokąd jedziecie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Na dworzec, rano. Dalej nie powiem, nie dlatego, że nie ufam. Dlatego, że nie wolno.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Ile lat ma Milo?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Sześć. W maju skończył. Nie chodził jeszcze do szkoły, bo szkoły są tam, gdzie zostawiamy adres.", "mina": "emocja"}, {"tekst": "Co jest w pozytywce?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Nic. Mechanizm i kurz. Proszę nie zdejmować dna.", "mina": "klamie"}, {"tekst": "Czy ktoś Was szuka?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie wiem. Dlatego pociąg jest o 5:40, a nie o dziewiątej.", "mina": "emocja"}, {"tekst": "Pod dnem leży bilet i kartonik z numerem 0623. Co to jest?", "ton": "niewygodne", "wymaga": "d12_pozytywka_0623", "odpowiedz": "Proszę, nie pytaj. To jest to, co zostało z trzech lat. Jeśli ktoś o tym usłyszy, Milo i ja nie dojedziemy.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czego potrzebujesz najbardziej?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Żeby Milo zasnął w pociągu. I żeby nikt tu nie zapisał mojego nazwiska obok jego imienia.", "mina": "mowi"}, {"tekst": "Podpisze odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Linh. Samo Linh, bez nazwiska. Jeśli musi być nazwisko, napisz mi, które mam podać.", "mina": "neutralna"}, {"tekst": "Żeton 0623 leży w depozycie. Wiesz o tym?", "ton": "rzeczowe", "wymaga": "d9_iris:depozyt", "odpowiedz": "Wiem, Iris mi powiedziała. Pociąg jest jutro, a depozyt do soboty. Czyli wyjadę bez papieru albo nie wyjadę wcale.", "mina": "emocja"}, {"tekst": "Numer 0623 jest na liście Victora. Wiesz o tym?", "ton": "rzeczowe", "wymaga": "d9_iris:zetony_victor", "odpowiedz": "Wiem. Iris mi powiedziała. Wsiądę, ale będę się rozglądać do ostatniego przystanku.", "mina": "emocja"}, {"tekst": "Kto Wam pomaga w tym wyjeździe?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Ktoś, kto bierze za to pieniądze i nie lubi, kiedy się o tym mówi. Więcej nie powiem.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Milo, patrz, gwiazdka wróciła. Nie pytam, co widać. Dziękuję, że nie pytasz.", "zysk": "Linh i Milo mają pozytywkę i bilet: rano wsiądą do pociągu o 5:40.", "strata": "Wydajesz rzecz z numerem Skrytki, więc jesteś w układzie Iris, a w księdze nie ma po tym śladu.", "echo": {"za_dni": 4, "forma": "list", "tekst": "Pocztówka z dworca, bez nadawcy: narysowana gwiazdka. Pod spodem: „Milo zasnął w połowie drogi. Dziękuję.”"}}, {"akcja": "zatrzymaj", "reakcja": "Rozumiem. Proszę tylko, żeby Milo tego nie słyszał. On się pamięta.", "zysk": "Kartonik z 0623 zostaje w biurze: masz w ręku dowód Skrytki.", "strata": "Linh i Milo mogą nie zdążyć na pociąg, a dziecko zostaje na ławce bez kołysanki.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Iris Bell: „Pewna matka z synem nie wsiadła rano do pociągu. Nie lubię naciskać, ale ktoś tu się pomylił, i będzie to droga pomyłka.”"}}], "sprite": "pozytywka", "face": null, "face2": null, "line": "11", "itemName": "pozytywka", "inside": null}, {"id": "d13_elias", "dzien": 13, "postac": "Elias Wren, 73", "glos": "Powoli, staroświecko, z uprzejmością, która ma coś zasłonić. Składa numerek w prostokąt. Kończy: „Dziękuję.”", "typ": "uczciwy-wstydliwy", "rzecz": "Futerał z oprawką okularów (bez szkieł)", "wnetrze": [{"sekret_id": "d13_kwit_zwrotu", "co_widac": "Za wyściółką futerału złożony kwit zwrotu pieniędzy: 85 $, podpis S. Holt. Numer paczki zgadza się z wykazem Skrytki.", "co_z_tego_wynika": "Oprawka przejechała przez kanał Iris. Sam zwrócił Eliasowi pieniądze za oprawkę z własnej kieszeni."}], "wejscie": "Elias Wren, numerek jeden. Oprawka okularów mojej żony wróciła tramwajem szóstym, tak mówi konduktor. Chcę ją odebrać. I chcę wiedzieć, dlaczego pan Holt zapłacił za nią z własnej kieszeni, bo ja nie prosiłem.", "tury": [{"pytania": [{"tekst": "Jak wygląda oprawka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Złota, cienka, jedno ucho wygięte. Żona prostowała je kciukiem, a ono i tak wracało. Czterdzieści jeden lat.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy zniknęła?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, tuż przed Bożym Narodzeniem, kiedy wracaliśmy od jej siostry. Potem zachorowała i okularów już nie założyła.", "mina": "mowi"}, {"tekst": "Czemu Sam za nią zapłacił?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo obiecał szukać. Nie znalazł, więc zapłacił, jakby to była jego wina. Dowiedziałem się, kiedy było już po wszystkim.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Z czego żyjesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Z emerytury, czterysta dziesięć dolarów miesięcznie. Nie narzekam, tylko liczę.", "mina": "mowi"}, {"tekst": "Kiedy Sam odszedł?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Pięć tygodni temu. Mówił: jeszcze nie, panie Eliasie. A potem przestał przychodzić.", "mina": "emocja"}, {"tekst": "Co wiesz o paczkach, które jeżdżą szóstką?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Że konduktor ich nie lubi. Więcej nie wiem i nie chcę wiedzieć.", "mina": "neutralna"}, {"tekst": "Kwit zwrotu ma numer paczki ze Skrytki. Co to znaczy?", "ton": "niewygodne", "wymaga": "d13_kwit_zwrotu", "odpowiedz": "Nie znam żadnej Skrytki. Wiem, że Sam powiedział: nie pytaj, skąd pieniądze. Wziąłem. Wstyd bywa jedyną zapłatą, jaka zostaje.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co chcesz zrobić z kwitem?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Chcę, żeby ktoś zapisał, że Sam zapłacił, a ja przyjąłem. Żeby to nie był dług bez nazwy. To dla niego, nie dla mnie.", "mina": "mowi"}, {"tekst": "Co zrobisz z pieniędzmi w kopercie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Oddam. Cztery tygodnie odkładałem po dwadzieścia jeden dolarów, żeby miał z czego jeść. Nie zadzwonię ani nie napiszę. Oddam do ręki.", "mina": "mowi"}, {"tekst": "Jak Sam zareaguje?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Odmówi. A ja nie odpuszczę. Tyle że on jest młodszy, a ja mam czas tylko do końca miesiąca.", "mina": "emocja"}]}], "decyzje": [{"akcja": "odpis_za_zgoda", "etykieta": "Poproś Eliasa o zgodę i zrób odpis kwitu", "reakcja": "Zgoda. Powiem to głośno: pan Holt zapłacił, ja przyjąłem. Proszę napisać dokładnie. Dziękuję.", "zysk": "Masz odpis kwitu i zeznanie Eliasa: dowód, że Sam zapłacił i że paczka jechała kanałem Iris.", "strata": "Elias staje się świadkiem w sprawie, której nie wybierał, i będzie o niej pamiętał.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Elias Wren: „Czy ktoś już pokwitował moje zeznanie? Proszę o numer. Jeśli nie, to jutro. — E.W.”"}}, {"akcja": "wydaj_od_reki", "etykieta": "Wydaj oprawkę z całą zawartością od ręki", "reakcja": "Dziękuję. Okulary żony. Jutro... nie, już nie jutro. Dziękuję.", "zysk": "Elias odbiera oprawkę bez pytań i wraca do domu spokojny.", "strata": "Kwit odchodzi z oprawką: nie masz dowodu na Sama ani na kanał Iris.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Elias przeszedł dziś obok okienka, skłonił głowę i poszedł dalej. Po raz pierwszy od trzynastu dni nie zapytał o oprawkę."}}], "sprite": "futeral", "face": null, "face2": null, "line": "4", "itemName": "futerał z oprawką", "inside": null}, {"id": "d13_odile", "dzien": 13, "postac": "Odile Faber, 68", "glos": "Głośna, wesoła, żartuje z własnych zębów. Mówi do wszystkich „dziecko”, nawet do urzędników.", "typ": "uczciwa-zawstydzona", "rzecz": "Niebieskie pudełko po herbatnikach", "wnetrze": [{"sekret_id": "d13_mandat", "co_widac": "W pudełku, na serwetce, leży proteza z wygrawerowanymi od spodu inicjałami O.F. Pod nią złożony mandat za jazdę bez biletu, bez pieczątki, z dopiskiem Leo: „zdarza się”.", "co_z_tego_wynika": "Odile jeździ bez biletu, a konduktor to przepuszcza. To nic dla sprawy, tylko ludzka rzecz."}], "wejscie": "Odile Faber, sześćdziesiąt osiem lat i trzydzieści dwa zęby, z czego dwadzieścia osiem moich. Zgubiłam protezę w pudełku po herbatnikach, szóstka, dziś rano. O dziesiątej ślub wnuczki, a zdjęcie rodzinne bez zębów to dla mnie kara.", "tury": [{"pytania": [{"tekst": "Jak wygląda pudełko?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Okrągłe, niebieskie, po duńskich herbatnikach. Wieczko zagięte, bo siadam na nim na przystanku. W środku serwetka w kwiatki.", "mina": "mowi"}, {"tekst": "Czemu proteza jest w pudełku po herbatnikach?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo w kieszeni by się pogniotła, a w szklance nie wypada. Pudełko jest szczelne i ładnie pachnie.", "mina": "mowi"}, {"tekst": "Czy jechałaś z biletem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Jak zawsze. Skasowany, w kieszeni, kochanie.", "mina": "klamie"}, {"tekst": "W pudełku jest mandat z dopiskiem Leo „zdarza się”. Co to znaczy?", "ton": "niewygodne", "wymaga": "d13_mandat", "odpowiedz": "Dziecko, emerytura to czterysta dolarów i zęby. Bilet kosztuje tyle, co obiad. A Leo to człowiek. Nie piszcie na niego.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Gdzie masz ślub?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Kościół świętej Łucji, dziesiąta rano. Wnuczka Frida, narzeczony z wąsami jak szczotka. Przysięgam, że ona go kocha.", "mina": "mowi"}, {"tekst": "Po czym poznasz protezę?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Od spodu mam wygrawerowane O.F. Dentysta powiedział: żeby ktoś nie zabrał. Nikt nie zabierze, ale grawer został.", "mina": "mowi"}, {"tekst": "Czy rodzina wie, że ją zgubiłaś?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nikt. Córce powiedziałam, że mam przeziębienie i jem zupę. Zęby to rzecz prywatna, dziecko.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Czego się boisz najbardziej?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Że zrobią mi zdjęcie z ustami jak w liście gończym. Wnuczka by nie powiedziała, ale ja bym pamiętała do końca życia.", "mina": "emocja"}, {"tekst": "Podpisze odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Odile Faber. Podpiszę, zaśpiewam, co zechcesz, byle szybko.", "mina": "neutralna"}, {"tekst": "Co zrobisz, jeśli proteza się nie znajdzie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Zjem ślub zupą i będę się uśmiechać ustami. Frida się nie obrazi, ale ja tak.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję, dziecko. Zdążę i wejdę do kościoła jak królowa. Leo dostanie ode mnie ciasto.", "zysk": "Odile zdąży na ślub, a Frida będzie miała babcię na zdjęciu z uśmiechem.", "strata": "Mandat Leo idzie dalej bez śladu, więc „zdarza się” zostaje regułą.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Odile Faber: „Zdjęcie wyszło cudownie. Wnuczka mówi, że wyglądam jak aktorka. Przesyłam kawałek tortu, dziecko.”"}}, {"akcja": "odmow", "reakcja": "Odmawiasz mi zębów? Dziecko, w takim razie zjem ślub zupą.", "zysk": "Nikt nie może Ci zarzucić wydania bez sprawdzenia.", "strata": "Odile idzie na ślub bez zębów i zapamięta to jako karę.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Odile Faber: „Frida mówi, że babcia wyglądała dzielnie. Dzielnie! Ząb za ząb, kochanieńki.”"}}], "sprite": "pudelko_blaszane", "face": null, "face2": null, "line": "6", "itemName": "pudełko po herbatnikach", "inside": null}, {"id": "d14_noah", "dzien": 14, "postac": "Noah Reyes, 42", "glos": "Spokojny, powtarza cudze słowa po swojemu: „Czyli: …”. Gdy coś pomija, mówi: „To moje zmartwienie.”", "typ": "uczciwy, pomija zamiast kłamać", "rzecz": "Czarny organizer z gumką w poprzek", "wnetrze": [{"sekret_id": "d14_projekt_oswiadczenia", "co_widac": "W kieszeni organizera leży kartka z propozycją oświadczenia i pustym miejscem na podpis: „do weryfikacji z M.D.”. Obok notatka: „relacja E.D. nie zgadza się z godzinami, sprawdzić 22:15”.", "co_z_tego_wynika": "Noah wie, że relacja Evana ma luki, i chce podpisu Mai, żeby zamknąć sprawę bez Evana."}], "wejscie": "Noah Reyes, komisariat. Zgubiłem organizer, czarny, z gumką, jedenastka. Mam w nim projekt oświadczenia w sprawie Mai Doyle i termin do dwudziestego drugiego. Czyli: bez organizera tracę dwa dni, a tyle mi nie zostało.", "wejscie_jesli": {"d11_maya:przez_okienko": "Noah Reyes, komisariat. Dostałem jedno zdanie od kogoś, kto zna sprawę Mai Doyle: żyje, nie wróci, nie szukać. Nie pytam skąd. Zgubiłem organizer z projektem oświadczenia. Czyli: bez niego nie zamknę sprawy do dwudziestego drugiego.", "d11_maya:powiadom_rodzine": "Noah Reyes, komisariat. Rodzina Mai Doyle dowiedziała się, że żyje, ale nic poza tym. Siostra dzwoniła trzy razy. Zgubiłem organizer z projektem oświadczenia. Czyli: bez niego sprawa rusza wyżej, a tego nikt nie chce."}, "tury": [{"pytania": [{"tekst": "Jak wygląda organizer?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, gumka w poprzek, ołówek w uchwycie. Notes równo z krawędzią. Zawsze równo, cokolwiek się dzieje.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy zniknął?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jedenastka, około dwudziestej trzeciej, po dyżurze. Zostawiłem go na siedzeniu, kiedy podnosiłem kobietę, która upadła. Czyli: zrobiłem coś dobrego i straciłem organizer.", "mina": "mowi"}, {"tekst": "Co jest w nim ważnego?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Notatki ze służby. Nic, co wolno pokazać. Proszę nie otwierać.", "mina": "neutralna"}, {"tekst": "W organizerze jest notatka o godzinach relacji Evana. Co z nią?", "ton": "niewygodne", "wymaga": "d14_projekt_oswiadczenia", "odpowiedz": "To moje zmartwienie. Powiem tyle: godziny nie pasują i wiem to od tygodnia. Czyli: nie pytaj dalej, bo nie mogę odpowiedzieć.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co powinno być w oświadczeniu?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Trzy zdania: że żyje, że wyjechała z własnej woli, że nie chce być szukana. Jej podpis, moja pieczątka. Czyli: koniec sprawy.", "mina": "mowi"}, {"tekst": "Do kiedy masz czas?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Do dwudziestego drugiego, północ. Potem zgłoszenie idzie do wydziału i zaczyna się szukanie z urzędu. Wtedy nikt już nie pyta o jej zgodę.", "mina": "mowi"}, {"tekst": "Ufasz Evanowi?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "To moje zmartwienie. Czyli: nie odpowiem, i proszę tego nie traktować jako odpowiedzi.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Co możesz obiecać Mai?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Że napiszę tylko to, na co się zgodzi. Czyli: bez adresu, bez miasta, bez nazwisk. Tyle mogę i tyle obiecuję.", "mina": "mowi"}, {"tekst": "Jak to wygląda, jeśli ona nie przyjdzie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Zgłoszenie przechodzi do wydziału i już nie decyduję. Czyli: im mniej mam na papierze, tym mniej mogę osłonić.", "mina": "mowi"}, {"tekst": "Dostałeś jedno zdanie od Mai. Co z nim zrobisz?", "ton": "rzeczowe", "wymaga": "d11_maya:przez_okienko", "odpowiedz": "Zapisałem słowo w słowo. Czyli: wiem, że żyje i że nie wróci. Brakuje mi tylko jej podpisu, żeby to było na papierze.", "mina": "mowi"}, {"tekst": "Czy Evan jest podejrzany?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie powiem. Powiem tylko, że w jego relacji jest godzina 22:15 i jedna ulotka. Czyli: rozbieżność, nic więcej.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "rezerwacja_d22", "etykieta": "Zarezerwuj poufną rozmowę Mai z Noahem na 22", "reakcja": "Zapisuję: poufna rozmowa dwudziestego drugiego, tutaj, przy okienku. Czyli: liczę na Ciebie.", "zysk": "Noah wstrzymuje przekazanie sprawy wyżej do wieczora 22, a Maya ma gdzie złożyć oświadczenie.", "strata": "Obiecujesz coś w imieniu Mai bez jej wiedzy; jeśli nie przyjdzie, Noah uzna to za grę na zwłokę.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Zarezerwowano rozmowę na dwudziestego drugiego. Czekam. Jeśli ona nie przyjdzie, wiem, że to moje zmartwienie, nie Wasze. — N. Reyes"}}, {"akcja": "bez", "etykieta": "Zostaw tryb zwykły, bez rezerwacji", "reakcja": "Czyli: bez zobowiązań. Dobrze. Zostaje to, co mam, i to, co zdążę.", "zysk": "Nie składasz obietnic w imieniu Mai ani nie pogarszasz jej sytuacji.", "strata": "Noah ma tylko to, co ma, i dwudziesty drugi może minąć bez rozmowy z Mayą.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Do 22 nic nie wpłynęło na piśmie, więc zgłoszenie przechodzi do wydziału. Nie moja decyzja. — N. Reyes"}}], "sprite": "organizer", "face": null, "face2": null, "line": "4", "itemName": "organizer", "inside": null}, {"id": "d14_billie", "dzien": 14, "postac": "Billie Cross, 16", "glos": "Szybko, z żartem, „no weź”, „serio?”. Przy strachu robi się jeszcze zabawniejsza.", "typ": "bluffer z dobrego serca", "rzecz": "Zielony kask z naklejkami w pandy", "wnetrze": [{"sekret_id": "d14_legitymacja", "co_widac": "Pod wyściółką kasku wsunięta legitymacja szkolna: Billie Cross, liceum, klasa pierwsza, rocznik sprzed szesnastu lat.", "co_z_tego_wynika": "Billie ma szesnaście lat, nie osiemnaście. Wagaruje, a kask jest jej biletem na trening."}], "wejscie": "Billie Cross, osiemnaście lat, dorosła. Kask z naklejkami, jedenastka, pętla przy parku. Hulajnogę mam, kasku nie, a bez kasku nie wpuszczą mnie na zajęcia. Bardzo ważne zajęcia.", "tury": [{"pytania": [{"tekst": "Jak wygląda kask?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Zielony, pęknięty z tyłu, naklejki z pandami. Jedna panda ma wąsy, bo dorysowałam. Poznasz od razu.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy go zgubiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jedenastka, rano, koło ósmej. Położyłam na siedzeniu, bo kask gniecie fryzurę. Fryzura jest ważna.", "mina": "mowi"}, {"tekst": "Ile masz lat?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Osiemnaście. Serio. Tak mi napisali w dowodzie.", "mina": "klamie"}, {"tekst": "Legitymacja w kasku mówi, że masz szesnaście lat.", "ton": "niewygodne", "wymaga": "d14_legitymacja", "odpowiedz": "No weź. Szesnaście i trzy czwarte. To prawie osiemnaście, jak się dobrze zaokrągli. Nie mów mamie.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co to za zajęcia?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Trening hulajnogi, freestyle. W szkole mówią, że to nie sport, więc robię to po lekcjach, czyli przed lekcjami. Wiesz.", "mina": "mowi"}, {"tekst": "Czemu nie jesteś w szkole?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo biologia. Biologia o ósmej to nie edukacja, to kara.", "mina": "mowi"}, {"tekst": "Czy ktoś wie, że tu jesteś?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Kuzynka. Tylko ona. Reszta myśli, że jestem u dentysty. Dentysta to świetne alibi.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Dokąd teraz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Na trening. A potem do szkoły, prawie na pewno, jeśli wszystko pójdzie dobrze.", "mina": "neutralna"}, {"tekst": "Podpisze odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Billie. Samo imię wystarczy, serio.", "mina": "neutralna"}, {"tekst": "Czemu nie powiesz prawdy o wieku?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo jak powiem, to dzwonią do mamy, a mama dzwoni do pani dyrektor. A pani dyrektor ma na mnie specjalną teczkę.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki! Panda z wąsami wraca do domu. Nie dzwońcie nigdzie, okej?", "zysk": "Billie ma kask i zdąży na trening.", "strata": "Wydajesz osobie, która skłamała o wieku, i nic z tym nie robisz.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Billie Cross: „Zajęcia były super. Wszyscy zazdrościli pandy z wąsami. Przyniosę wam naklejkę.”"}}, {"akcja": "wydaj_z_poucz", "etykieta": "Wydaj i powiedz, że wiesz, ile ma lat", "reakcja": "No dobra, szesnaście. Ale nie dzwońcie, proszę. Nic się nie stało.", "zysk": "Billie wie, że ktoś zna prawdę i nie robi z tego dramatu.", "strata": "Billie może przestać przychodzić po swoje rzeczy, bo przy szybie nie da się blefować.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Billie Cross: „Dzięki, że nikt nie dzwonił. Poszłam na biologię. Raz. Przyniosę naklejkę.”"}}], "sprite": "czapka_daszek", "face": null, "face2": null, "line": "11", "itemName": "kask", "inside": null}, {"id": "d15_sam", "dzien": 15, "postac": "Sam Holt, 44", "glos": "Krótko, technicznie. Najpierw szczegół („klamra była lewostronna”), prawdę dopiero po dopytaniu. Suchy humor, ciepło w szczegółach.", "typ": "uczciwy-wstydliwy, zasłania się technikaliami", "rzecz": "Szary termos z pokrywką lewozwojną", "ludzie": {"sam": "Sam Holt", "vera": "Vera Kovacs"}, "wnetrze": [{"sekret_id": "d15_termos_kwit", "co_widac": "Pod wkładką termosu leży zegarek na pasku i kwit zastawu: 85 $, data dzień po dacie na kwicie zwrotu dla Eliasa.", "co_z_tego_wynika": "Sam zastawił zegarek, żeby zapłacić Eliasowi za oprawkę. Potwierdza to kwit z dnia 13."}], "wejscie": "Sam Holt. Vera mnie wezwała, więc jestem. Po termos i rzeczy z szafki, bez wielkich słów. Termos szary, wgniecenie przy dnie, pokrywka lewozwojna. Zanim wejdzie Victor, chcę wiedzieć jedno: kto zaglądał do szuflady, w której trzymałem papiery?", "wejscie_jesli": {"d10_vera:pokwituj_osobista": "Sam Holt. Vera pisała, że moje rzeczy pokwitowano jako osobiste, a nie do archiwum. To dla mnie coś znaczy. Po termos i rzeczy z szafki, szary, pokrywka lewozwojna. Zanim wejdzie Victor: kto zaglądał do szuflady z moimi papierami?", "d10_vera:archiwum": "Sam Holt. Moje rzeczy trafiły do zbiorczego archiwum Urzędu, więc ktoś obcy czyta teraz moje akta. Po termos i szafkę, szary, pokrywka lewozwojna. Zanim wejdzie Victor, zapytam wprost: kto zaglądał do szuflady?"}, "tury": [{"pytania": [{"tekst": "Jak wygląda termos?", "ton": "uprzejme", "kto": "sam", "wymaga": null, "odpowiedz": "Szary, wgniecenie przy dnie, pokrywka lewozwojna: odkręca się w prawo, bo fabryka się pomyliła. Mam go od trzynastu lat.", "mina": "mowi"}, {"tekst": "Co jest w środku?", "ton": "rzeczowe", "kto": "sam", "wymaga": null, "odpowiedz": "Zimna herbata od wczoraj. Nic więcej.", "mina": "klamie"}, {"tekst": "Czemu jeszcze jesteś w mieście?", "ton": "niewygodne", "kto": "sam", "wymaga": null, "odpowiedz": "Bo w porcie czekają na referencje z Urzędu, do dwudziestego piątego. Bez papieru etat idzie do kogoś innego.", "mina": "mowi"}, {"tekst": "W termosie jest zegarek i kwit zastawu. Po co?", "ton": "rzeczowe", "kto": "sam", "wymaga": "d15_termos_kwit", "odpowiedz": "Po to, żeby oddać Eliasowi osiemdziesiąt pięć dolarów. Zastawiłem zegarek. Nie pytaj, czy żałuję. Żałuję, że nie dość.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Jak minęło Ci pięć tygodni?", "ton": "uprzejme", "kto": "sam", "wymaga": null, "odpowiedz": "Dźwigam skrzynie w porcie. Plecy bolą, ale nie ma żadnej księgi. Sen nie przychodzi. Sen miał pozycje.", "mina": "mowi"}, {"tekst": "Które klucze pasują do szuflady?", "ton": "rzeczowe", "kto": "vera", "wymaga": null, "odpowiedz": "Pierwszy to ten, który poprzednik zostawił w pierwszą sobotę. Drugi mam ja, dostałam go od Sama. Dwa zamki, żeby jedna osoba nie mogła sama.", "mina": "mowi"}, {"tekst": "Co jest w szufladzie?", "ton": "niewygodne", "kto": "sam", "wymaga": null, "odpowiedz": "Rachunki. Stare grafiki. Nic, co by się komukolwiek przydało.", "mina": "klamie"}, {"tekst": "W szufladzie jest kalka strony 41. Co się z nią stało?", "ton": "niewygodne", "kto": "sam", "wymaga": "d15_kalka_41", "ustawia": "d15_sam_klamra", "odpowiedz": "Klamra była lewostronna. Kartka puściła przy marginesie. Technicznie to nie wyrwanie, tylko wypięcie.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Czego od nas chcesz?", "ton": "uprzejme", "kto": "sam", "wymaga": null, "odpowiedz": "Moich rzeczy i prawa do własnych słów. Resztę zostawiam Wam, pod jednym warunkiem: nikt nie wpisuje mnie do protokołu bez pytania.", "mina": "mowi"}, {"tekst": "Elias złożył zeznanie za kwit. Co o tym myślisz?", "ton": "uprzejme", "kto": "sam", "wymaga": "d13_elias:odpis_za_zgoda", "odpowiedz": "Nie prosiłem o to. Ale to dla mnie coś znaczy, że powiedział to głośno. Chcę, żeby nie poszło na marne.", "mina": "emocja"}, {"tekst": "Elias dostał oprawkę bez zeznania. Co o tym myślisz?", "ton": "uprzejme", "kto": "sam", "wymaga": "d13_elias:wydaj_od_reki", "odpowiedz": "Dobrze, że ją ma. Szkoda, że kwit pojechał razem z nią. Sam bym go zostawił, ale to nie moja księga.", "mina": "mowi"}, {"tekst": "Co z referencjami do dwudziestego piątego?", "ton": "rzeczowe", "kto": "sam", "wymaga": null, "odpowiedz": "Port dzwoni do biura 25 o 5:30. Jeśli Victor nic na mnie nie ma, dadzą papier. Jeśli ma, nie dadzą.", "mina": "mowi"}, {"tekst": "Dlaczego nie przyszedłeś wcześniej?", "ton": "niewygodne", "kto": "sam", "wymaga": null, "odpowiedz": "Bo Vera napisała o piętnastym i jak ktoś każe być w sobotę, to jest. Poza tym bałem się zobaczyć szafkę.", "mina": "mowi"}, {"tekst": "Czemu wypiąłeś stronę 41?", "ton": "niewygodne", "kto": "sam", "wymaga": "d15_sam_klamra", "odpowiedz": "Wyrwałem, żeby nikt nie miał tych nazwisk. Czternaście rodzin i podpis kogoś, kto to potem zatwierdził. Jak pójdą do Urzędu, pójdą też do wyroków.", "mina": "emocja"}]}], "decyzje": [{"akcja": "uzgodnij", "etykieta": "Uzgodnij z Samem zakres, Victorowi odpis zasłonięty", "kto": "sam", "reakcja": "Zasłonić nazwiska, zostawić liczby. Zgoda. Po kolei: oni, potem ja.", "zysk": "Sam zostaje po Twojej stronie i zachowuje referencje. Victor widzi liczby, nie ludzi.", "strata": "Dowód słabnie: Nora dostaje kalkę z zasłoniętymi nazwiskami, bez pełnego dowodu.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dostałem zapewnienie z portu, jeszcze nie papier, ale będzie. Dziękuję za kreskę zamiast nazwisk. — S.H."}}, {"akcja": "victor_od_razu", "etykieta": "Przekaż kalkę Victorowi od razu", "kto": "sam", "reakcja": "Rozumiem. Wycofuję zgodę. Nic dla Urzędu nie podpisuję.", "zysk": "Mocny dowód: pełna kalka i podpis Victora na zatwierdzeniu trafiają do Urzędu.", "strata": "Ludzie z listy są w rękach Urzędu, Sam wycofuje zgodę, a referencje wiszą.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Odebrałem kalkę z szuflady. Zatwierdzenie z moim podpisem wymaga wyjaśnienia, nie ukrywam. Wrócę do tego w sobotę. — V. Crane"}}], "sprite": "termos", "face": null, "face2": {"sam": null, "vera": null}, "line": "6", "itemName": "termos", "inside": {"img": "W13", "x": 0.3, "y": 0.2}}, {"id": "d15_pruitt", "dzien": 15, "postac": "Pruitt, 80", "glos": "Powoli, pogodnie. Co zdanie upewnia się: „wszystko w porządku, prawda?”. Nazwisko podaje z dwoma t.", "typ": "uczciwy-samotny", "rzecz": "Pęk jedenastu parasoli w jednym uchwycie", "wnetrze": [{"sekret_id": "d15_parasol_ew", "co_widac": "Jeden z parasoli ma wygięty uchwyt i naklejkę z inicjałami E.W., a w rączce zatknięty składany w prostokąt numerek z biura.", "co_z_tego_wynika": "To parasol Eliasa Wrena, który wrócił z dalekiego końca linii."}], "wejscie": "Pruitt, osiemdziesiąt lat, więc proszę nie biec. Przyniosłem jedenaście parasoli, zbierałem je od wtorku w czwórce i trójce. Nikt po nie nie przyszedł, a to znaczy, że wszystko w porządku. Prawda?", "tury": [{"pytania": [{"tekst": "Gdzie je zbierałeś?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "W czwórce i trójce, na siedzeniach i pod nimi. W trójce więcej, bo tam siedzą ludzie, którzy lubią zostawiać po sobie ślad.", "mina": "mowi"}, {"tekst": "Ile ich jest?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jedenaście. Cztery czarne, trzy granatowe, dwa w kratę, jeden z kaczkami i jeden bez rączki. Liczyłem trzy razy.", "mina": "mowi"}, {"tekst": "Czemu myślisz, że wszystko w porządku?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo jakby komuś zależało, już by przyszedł. Parasol to nie portfel, za parasolem nikt nie płacze. Prawda?", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co robisz w tramwajach całymi dniami?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Jeżdżę. Z żoną jeździliśmy codziennie, od przystanku do pętli i z powrotem. Teraz jeżdżę sam, ale tak samo.", "mina": "emocja"}, {"tekst": "Który parasol najbardziej Ci się podoba?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Ten z kaczkami. Wiem, głupio. Ale kaczki są w porządku.", "mina": "mowi"}, {"tekst": "Parasol bez rączki ma naklejkę E.W. Czyj to?", "ton": "rzeczowe", "wymaga": "d15_parasol_ew", "odpowiedz": "Nie wiem. Starszy człowiek, tak sądzę. W jedenastce siedział z numerkiem w ręku i składał go w prostokąt, aż zrobił się kamień.", "mina": "mowi"}, {"tekst": "Jak często jeździsz bez celu?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Codziennie. Cel to znaleźć kogoś, kto powie: dziękuję.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz, jeśli nikt nie przyjdzie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Zjem sam obiad i zadzwonię do syna, że wszystko w porządku. Będzie wiedział, że kłamię, ale się ucieszy.", "mina": "emocja"}, {"tekst": "Podpisze oddanie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Pruitt. Z dwoma t. Zawsze ktoś pisze z jednym.", "mina": "mowi"}, {"tekst": "Czemu oddajesz parasole do biura?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo tu jest ktoś w okienku. Nawet w nocy. To wiele znaczy, wiesz?", "mina": "emocja"}]}], "decyzje": [{"akcja": "zatrzymaj", "reakcja": "Dziękuję. Proszę dać im komuś, jak będzie padało. Ja będę przechodził.", "zysk": "Jedenaście parasoli ma półkę, a Pruitt ma powód, żeby wrócić.", "strata": "Półka się zapełnia, a w magazynie robi się ciaśniej.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Elias Wren: „Dziękuję za parasol. Pan Pruitt twierdzi, że znalazł go na jedenastce. Był bez rączki od burzy. Czy jest oprawka? Jutro.”"}}, {"akcja": "odmow", "reakcja": "Rozumiem. Zaniosę z powrotem. Parasol to nie portfel, nikt nie zauważy.", "zysk": "Nie dokładasz do sterty i nie musisz szukać półki.", "strata": "Pruitt wraca z jedenastoma parasolami i prawdopodobnie przestanie przychodzić.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Na pętli czwórki ktoś zostawił jedenaście parasoli oparte o słup. Nikt ich nie wziął. Leo zapisał to w wykazie zmiany jako „sprawa porządkowa”."}}], "sprite": "parasol", "face": null, "face2": null, "line": "4", "itemName": "parasole", "inside": null}];window.EXTRA={"2": {"sprite": "szalik", "itemName": "szalik", "line": "4", "inside": null, "wnetrze": [{"sekret_id": "d2_szalik_md", "co_widac": "Pod zagiętą metką wyhaftowane inicjały M.D. W wewnętrznej kieszonce złożony bilet miesięczny na linię 4, imienny: Maya Doyle.", "co_z_tego_wynika": "Szalik należy do Mai Doyle, którą mąż zgłosił jako zaginioną. Maya zostawiła go w tramwaju."}]}, "6": {"sprite": "puszka", "itemName": "puszka po herbacie", "line": "6", "inside": {"img": "W4", "x": 0.23, "y": 0.44}, "wnetrze": [{"sekret_id": "d6_puszka_odcinek", "co_widac": "Pod ruchomym dnem puszki leży odcinek odbioru. Numer jest z tego samego bloczka co blankiet w płóciennej paczce Iris Bell z dnia czwartego.", "co_z_tego_wynika": "Puszka należy do obiegu paczek Skrytki."}]}, "15": {"sprite": "koperta", "itemName": "koperta z szuflady", "line": "4", "inside": null, "wnetrze": [{"sekret_id": "d15_kalka_41", "co_widac": "Szuflada ma dwa zamki: pierwszy otwiera klucz poprzednika, drugi klucz od Very. W środku kalka wyrwanej strony 41: czternaście wpłat lokatorów i pozycje Skrytki.", "co_z_tego_wynika": "Strona 41 istniała. Są na niej wpłaty lokatorów i numery odbioru."}, {"sekret_id": "d15_zatwierdzenie_victora", "co_widac": "Obok kalki leży zatwierdzenie rozliczenia z podpisem V. Crane i dopiskami innym tuszem. Data jest wcześniejsza niż audyt.", "co_z_tego_wynika": "Victor zatwierdził rozliczenie, wiedząc, że brakuje strony 41, i dopisał ślady po fakcie."}]}};window.WIECZOR={"1": [{"kto": "Elias, numerek 1", "tekst": "Elias przyszedł pod koniec zmiany. „Czy jest już oprawka po mojej żonie?” Nie było. Podziękował i długo stał przy szybie, jakby miało się coś zmienić."}], "2": [{"kto": "Elias, numerek 1", "tekst": "Elias, ten sam numerek. Zapytał o oprawkę, a potem, czy poprzedni pracownik zostawił jakąś notatkę o jej szukaniu. Nie zostawił."}, {"kto": "Kartka pod drzwiami domu", "tekst": "„Kuba Marlow. Trzysta dolarów, rata sześćdziesiąt w każdą sobotę. Lubię ludzi punktualnych. Nie krzyczę, tylko przypominam.” Nie wiesz, skąd wiedział, gdzie mieszkasz."}], "3": [{"kto": "Elias, numerek 1", "tekst": "Burza. Elias przyszedł w deszczu, z parasolem bez rączki. „Czy jest oprawka?” Nie było. Wziął suchy numerek i złożył go w prostokąt ciaśniejszy niż zwykle."}], "4": [{"kto": "Elias, numerek 1", "tekst": "Elias powiedział, że poprzedni pracownik obiecał szukać oprawki z własnej kieszeni. Zapytany, co to znaczy, odpowiedział, że nie wie, czy wolno mu mówić."}, {"kto": "Kuba Marlow, przez sąsiadkę", "tekst": "Sąsiadka powiedziała, że ktoś pytał, czy jesteś w domu. Odpowiedziała, że pracujesz w nocy. „To dobrze”, miał powiedzieć. „Noc to czas na pieniądze.”"}], "5": [{"kto": "Elias, numerek 1", "tekst": "Elias przyniósł gazetę. Na trzeciej stronie apel o Maję Doyle: trzydzieści cztery lata, krótkie czarne włosy, płaszcz z za długimi rękawami. „Taka młoda. Zgubiona.” Zapytał o oprawkę. Nie było. Gazeta została na ladzie."}], "6": [{"kto": "Elias, numerek 1", "tekst": "Elias zapytał o oprawkę i dodał, że poprzedni pracownik zawsze przedstawiał się z imienia. Nikt mu jeszcze nie powiedział, jak nazywa się osoba za szybą."}, {"kto": "Kuba Marlow, pod bramą zajezdni", "tekst": "Stał po drugiej stronie ulicy. Nie podszedł. Uniósł rękę i pokazał sześć palców: rata, sześćdziesiąt dolarów. Potem poszedł, jakby nic się nie stało."}], "7": [{"kto": "Elias, numerek 1", "tekst": "Elias: „On wiedział, że nie będzie. Mówił: jeszcze nie, panie Eliasie. A potem przestał mówić.” Wziął numerek i wyszedł wolno."}], "8": [{"kto": "Elias, numerek 1", "tekst": "Elias zostawił papierowy woreczek z dwoma ciastkami z cukierni obok. „To nie łapówka. To za nocne.” Zapytał o oprawkę. Nie było."}, {"kto": "Kuba Marlow, przez kuzyna", "tekst": "Kuzyn przyniósł kartkę: „Rata sześćdziesiąt, plus piętnaście odsetek za spóźnienie. K.M.” Powiedział, że Kuba nie jest zły, tylko nie lubi czekać."}], "9": [{"kto": "Elias, numerek 1", "tekst": "Elias poprosił, żeby oprawkę, jeśli się znajdzie, trzymać osobno. „Gdyby ktoś przyszedł po nią z papierkiem od innego pracownika, proszę nie wierzyć.”"}], "10": [{"kto": "Elias, numerek 1", "tekst": "Elias: „Pytam, bo on mi oddał pieniądze za oprawkę. Nie chciałem ich. Leżą u mnie w kopercie. Jak oprawka się znajdzie, oddam kopertę.” Numerek złożył w prostokąt bardzo ciasny."}, {"kto": "Kuba Marlow, po wypłacie", "tekst": "Czekał pod bramą z zeszytem w ręku. Powiedział: „Rata to nie wszystko. Można się dogadać inaczej, jak ktoś ma dostęp do rzeczy, które ludzie zostawiają w tramwajach.” Poszedł, zanim zdążyłeś odpowiedzieć."}], "11": [{"kto": "Elias, numerek 1", "tekst": "Elias zapytał, jak zwykle, o oprawkę. Dziś po raz pierwszy dodał: „Dziewczynka z królikiem powiedziała, że ktoś tu mnie poznaje.” Nie wiedział, czy to dobrze."}], "12": [{"kto": "Elias, numerek 1", "tekst": "Elias: „Pytałem dziś Leo, czy szóstka wozi rzeczy bez nadawcy. Powiedział, że jutro będzie miał dostawę, której nie rozumie.” Numerek złożył w prostokąt tak ciasny, że stał sam."}], "13": [{"kto": "Elias, numerek 1", "tekst": "Elias o oprawkę dziś nie pytał. Zapytał: „Czy Sam już był?” Numerek złożył jak zawsze, ale stał przy szybie dłużej niż zwykle."}], "14": [{"kto": "Elias, numerek 1", "tekst": "Elias: „Czy Sam już był?” Nie było. Powiedział, że koperta z osiemdziesięcioma pięcioma dolarami leży w kieszeni płaszcza i że nie wie, jak podać ją komuś, kto nie chce jej wziąć."}], "15": [{"kto": "Elias, numerek 1", "tekst": "Elias przyszedł pod koniec zmiany: „Czy Sam już był?” Kiedy usłyszał, że był, usiadł na ławce przy wejściu i długo nie wstawał. Numerka nie złożył."}]};window.LANG={"title": "OKIENKO", "sub": "Nocna zmiana w biurze rzeczy znalezionych. Tydzień pierwszy.", "start": "Zacznij zmianę", "settings": "Ustawienia", "close": "Zamknij", "day": "Dzień", "delivery": "Dziś z tramwajów: {n} {rz}. Zanim ktoś zapuka, zdążysz obejrzeć jedną od środka.", "look": "Zajrzyj", "skip": "Nie zaglądam, otwieram okienko", "line": "Linia", "inspect_hint": "Przeszukaj rzecz. Kliknij to, co nie pasuje.", "found": "Wiesz coś, czego nie powinieneś.", "open": "Otwórz okienko", "nothing": "Zwykła rzecz. Czasem parasol jest po prostu parasolem.", "knock": "Ktoś puka w szybę.", "let_in": "Odsuń zasłonkę", "know": "wiesz ze środka", "turn": "Odwróć się do magazynu", "search": "Znajdź w magazynie", "search_p": "Wybierz skrzynię wg linii, potem przekopuj. Kliknij rzecz, którą bierzesz.", "wrong": "To nie ta rzecz:", "wrong_line": "Tu tej rzeczy nie ma. Spróbuj inną linię.", "decide": "Rzecz leży na ladzie. Przeciągnij ją albo wybierz.", "wydaj": "Wydaj: przez okienko", "odmow": "Odmów: do skrzyni", "zatrzymaj": "Zatrzymaj: na półkę", "zadzwon": "Zadzwoń po dyżurnego", "next": "Dalej", "evening": "Świt. Poczta na ladzie.", "nomail": "Dziś nikt nie napisał.", "week_h": "Sobota. Rozliczenie.", "pay": "Wypłata", "rent": "Czynsz", "balance": "Zostaje", "drawer": "W szufladzie leży klucz bez zamka. Poprzednik nie zabrał wszystkiego.", "again": "Zacznij od nowa", "next_day": "Następny dzień", "dollar": "$", "vol_master": "Głośność ogólna", "vol_music": "Muzyka", "vol_amb": "Ambient", "vol_sfx": "Efekty", "vol_voice": "Głosy", "reduce": "Ogranicz błyski i wstrząsy", "end": "Koniec dostępnych dni. Dalej: dni, które jeszcze piszemy.", "storm": "Burza. Grom zrzucił skrzynie z półki: rzeczy leżą w innych skrzyniach niż zapisano.", "up_h": "Ulepszenie biura (jedno na sobotę)", "up_none": "Nic nie kupuję", "up_lampa": "Wymień lampę (mruganie ustaje, w biurze robi się nudno)", "up_drzwi": "Uszczelnij drzwi (deszcz za szybą ciszej)", "up_regal": "Dołóż regał (rzeczy ułożone alfabetycznie, skrzynie mieszczą więcej)", "owned": "kupione", "week2": "Następny tydzień", "rent2": "Czynsz za tydzień", "end_zag_A": "Przychodzi pocztówka bez nadawcy z jednym słowem: „Dziękuję”. Evan dostaje suknię. To cała odpowiedź, jaką dostaje. Noah zamyka zgłoszenie.", "end_zag_B": "Noah potwierdza, że Maya jest bezpieczna, i zamyka zgłoszenie. Lena kładzie na ladzie jeden klucz, ten od mieszkania, które Maya zostawiła, i pyta, czy ktoś kiedyś po niego przyjdzie.", "end_zag_C": "Maya przychodzi już tylko po walizkę, bez rozmów, i wyjeżdża na własnych warunkach. Evan wynajmuje detektywa. Lena stoi przy okienku bez Mai i pyta, czy coś zostało po jej siostrze. Gracz wie, że zostało wszystko.", "end_skr_A": "Nora odbiera komplet. Okoye nie płacą drugi raz, a Iris podpisuje rozliczenie i oddaje 6 800 $. Grace Okoye w szpitalnym fartuchu kładzie na ladzie pączek w papierze: „Z dyżuru.”", "end_skr_A2": "Nora ma papiery, ale Iris kwestionuje ich autentyczność i sprawa idzie do sądu poza tą nocą. Grace Okoye kładzie na ladzie pączek w papierze: „Z dyżuru.” Nie wie jeszcze, czy zapłaci drugi raz.", "end_skr_B": "Victor zamyka obieg paczek, przyjmuje oryginały do audytu i zajmuje 6 800 $ jako dowód. Ludzie z żetonów są w aktach. Przychodzi zimny list z Urzędu, a w kolejnym wierszu nazwisko, które znasz z twarzy.", "end_skr_C": "Iris zabiera paczkę, oryginały i 6 800 $. Nora ma kopię jednej wpłaty, resztę będzie musiała odtworzyć. Kamienica o świcie, ekipa rozbiórki. Iris nie ma jej w oknie.", "end_pop_A": "Sam podpisuje zeznanie, Victor dopisuje własny podpis sprzed pięciu tygodni i wycofuje wpis obciążający Sama. Sam wychodzi. Elias siada na krześle poczekalni po raz pierwszy, odkąd pamięta, i czeka na tramwaj, jakby nigdzie się nie spieszył.", "end_pop_B": "Sam odbiera swoje rzeczy i wychodzi, nie odwracając się. W protokole zostaje niedobór. Wyjaśnienie krąży tylko między osobami, które zgodziły się mówić.", "end_pop_C": "Sam, wystawiony, dostaje od Iris pusty bilet bez numeru i znika. Zostawia u Very kopertę z 85 $ dla Eliasa. Elias odmawia jej przyjęcia i składa numerek w najciaśniejszy prostokąt, jaki widziałeś.", "ep_nowysam": "Victor zapisuje niedobór na twojej zmianie. Wypowiedzenie, rzeczy spakowane w pudełku. Następnego wieczoru przychodzi nowy pracownik i pyta o brakującą stronę.", "ep_nowysam_tear": "Victor zapisuje niedobór na twojej zmianie. Wypowiedzenie, rzeczy w pudełku. Wyrwana strona leży już gdzie indziej. Następnego wieczoru przychodzi nowy pracownik i pyta o brakującą stronę.", "ep_referent": "Umowa przedłużona, awans na starszego referenta, wypłata z premią. Zostajesz w okienku.", "ep_referent_tear": "Umowa przedłużona, awans na starszego referenta. W księdze brakuje twojej strony i nikt o nią nie pyta. Zostajesz w okienku jako następny przechowawca.", "ep_zostajesz": "Czynsz zapłacony, umowa przedłużona. Nikt tego nie świętuje.", "ep_zostajesz_tear": "Czynsz zapłacony, umowa przedłużona. W księdze brakuje twojej strony, tak jak po poprzedniku. Jesteś następnym przechowawcą.", "elias_A": "„Czy ktoś jeszcze czeka?”", "elias_B": "„Do jutra.”", "elias_C": "(milczy i kładzie numerek na ladzie)", "elias_N": "„Czy Sam już był?” (do tego, kto siedzi w okienku jutro)", "stock": "W skrzyni", "sorted": "ułożone alfabetycznie", "due": "do soboty", "bills": "Rachunki i jedzenie", "you_ask": "Pytasz:", "audit": "Victor policzył gotówkę w szufladzie i nie zgadza się z zapisami. Potrącenie: {f} $. Zapisał to na twojej zmianie.", "step_delivery": "Krok 1: kliknij rzecz, do której chcesz zajrzeć (albo „Nie zaglądam”)", "step_inspect": "Szukaj śladów: kliknij w obrazie to, co wygląda nie na miejscu", "step_knock": "Krok 2: kliknij „Odsuń zasłonkę”", "step_ask": "Krok 3: kliknij jedno z trzech pytań na dole", "step_turn": "Krok 4: kliknij „Odwróć się do magazynu”", "step_pile": "Krok 5: wybierz skrzynię, kliknij rzecz z opisu", "step_decide": "Krok 6: przeciągnij rzecz na szybę albo kliknij jedną z opcji po prawej", "tut_h": "Jak grać", "tut_ok": "Zaczynam zmianę", "tut_l": ["Tramwaje zostawiają rzeczy w skrzyniach. Każda linia ma swoją skrzynię.", "Możesz zajrzeć do jednej rzeczy od środka: kliknij ją, potem klikaj w obraz, aż coś nie będzie pasować.", "Kliknij „Odsuń zasłonkę”: ktoś przyszedł po swoją rzecz.", "Zadaj trzy pytania, klikając je. Słuchaj uważnie: ktoś może kłamać.", "Odwróć się do magazynu, wybierz skrzynię i kliknij właściwą rzecz według opisu na górze.", "Przeciągnij rzecz na szybę, żeby ją wydać, albo kliknij inną opcję. Każda ma cenę."], "dt": ["Rękawiczki na grobie", "Pierścionek w plecaku, szalik na wieszaku", "Dwie osoby, jeden telefon", "Koperta na ladzie, nikt jej nie dotyka", "Gazeta z twarzą Mai na ladzie", "Królik na ladzie, bilet na mokrym papierze", "Klucz, który otwiera nieznane drzwi", "Żółta kartka w podszewce", "Pięć żetonów w piórniku", "Pudełko po człowieku, który tu nie wraca", "Ktoś opisuje własne okulary, zanim je zobaczy", "Dwie kasetki, jedna torba na zakupy", "Oprawka, która wróciła z cudzego wozu", "Notes równo z krawędzią lady", "Klucz i szuflada", "Dwie siostry, jedno okienko", "List, który nie ma adresata", "Trzysta dolarów na ladzie", "Dziecko, które widziało za dużo", "Dwóch mężczyzn i koperta z 85 dolarami", "Dwie walizki, jedna jedzie na ślub", "Sztywna koperta i szary kapelusz", "Trzy osoby po jedną kasetkę", "Kartonik z numerem szafki", "Księga otwarta na twojej stronie"], "kartka_h": "Kartka przyklejona do skrzynki", "notes_b": "Notatnik", "notes_h": "Notatnik: kartki znalezione w rzeczach", "pr1_lab": "Słup przy zajezdni · 22:50", "pr1_txt": "POSZUKIWANY DYŻURNY. Nocne biuro rzeczy znalezionych, zmiana 23:40–6:00. 40 $ za wizytę. Pokój służbowy w cenie. Zgłosić się do Zarządu Nieruchomości Cooper.", "pr1_strip": "Oderwij pasek z numerem", "pr1_num": "Na pasku jest numer. Deszcz rozlał go tak, że nie da się go odczytać.", "pr1_next": "Idź do biura", "pr1_step": "Kliknij „Oderwij pasek”", "pr2_lab": "Umowa o pracę nocną · Zarząd Nieruchomości Cooper", "pr2_rows": ["Stanowisko: dyżurny", "Imię i nazwisko: ______________", "Miejsce pracy: biuro rzeczy znalezionych, pokój służbowy przy Cooper Street 9", "Wynagrodzenie: 40 $ za wizytę", "Podpis zarządcy: nieczytelny"], "pr2_btn": "Podpisz i zacznij zmianę", "pr2_step": "Kliknij, żeby zacząć pierwszą noc", "name_h": "Jak cię zapisać?", "name_s": "Wpisz cokolwiek. To imię wróci w księdze.", "name_p": "imię", "name_ok": "Zapisz", "name_def": "dyżurny", "ledger_h": "Księga wydań leży otwarta na twojej ostatniej stronie.", "ledger_s": "Co robisz z księgą?", "ledger_write": "Wpisz siebie: {n}", "ledger_tear": "Wyrwij stronę", "ledger_letter": "Zostaw list dla następcy", "ledger_close": "Zamknij księgę", "ledger_b": "Księga", "gest_wpisz": "W linii 0809 stoi teraz twoje imię. Następny dyżurny zacznie od niego.", "gest_wyrwij": "Strona leży wyrwana, tak jak po poprzedniku. Ludzie, których chroniłeś, nie mają już śladu w papierze, a ty nie masz obrony.", "gest_list": "Zostawiasz list w szufladzie. Następny dyżurny znajdzie go pierwszej nocy.", "gest_zamknij": "Zamykasz księgę. Nikt nie wie, czy to była decyzja.", "ledger_none": "Nic nie ruszam", "ledger_fix": "Dopisz sprostowanie", "urzad": "Urząd", "ludzie": "Ludzie", "debt": "Tydzień zamknięty z długiem.", "final_h": "Koniec zmiany. Dzień 25.", "th_zag": "Zaginiona", "th_skr": "Skrytka", "th_pop": "Poprzednik", "you": "Ty", "elias": "Ostatnie pytanie Eliasa", "eve_note": "Poza okienkiem", "soon": "Dalej: dni, które jeszcze piszemy."};